        if math.abs(p.x-p.y)<1400 then return 'mid' end
        return p.y>p.x and 'top' or 'bot'
    end
    function M.home(s)
        for _,u in ipairs(s.structures) do if u.team==s.hero.team and u.name:find('fountain') then return u.pos end end
