        local enemy=0
        for _,u in ipairs(B.near(s.allies,p,r)) do if u.alive then ally=ally+strength(u) end end
        for _,u in ipairs(B.near(s.enemies,p,r)) do if u.alive then enemy=enemy+strength(u) end end
        -- A friendly tower changes a short defensive trade, not distant fights.
        for _,t in ipairs(s.towers) do
            if t.alive and t.team==s.hero.team and B.dist(t.pos,p)<t.range then ally=ally+0.75 end
        end
        return ally,enemy
    end
    function T.at(s,p)
        local risk=0
        for _,t in ipairs(s.towers) do
            if t.team~=s.hero.team and t.alive and B.dist(t.pos,p)<t.range+160 then risk=risk+5 end
        end
        local a,e=T.balance(s,p,1100)
        risk=risk+math.max(0,e-a)*2
        for _,eUnit in ipairs(s.enemies) do
            if B.dist(p,eUnit.pos)<eUnit.range+200 then risk=risk+0.65 end
        end
        for _,c in ipairs(s.creeps) do
            if c.team~=s.hero.team and B.dist(p,c.pos)<c.range+100 then risk=risk+(s.time<600 and 0.28 or 0.08) end
        end
        -- Unseen route portions are uncertain, never treated as confirmed empty.
        local lit=B.dist(s.hero.pos,p)<650
        for _,u in ipairs(s.allies) do if u.alive and B.dist(u.pos,p)<650 then lit=true end end
        for _,u in ipairs(s.creeps) do if u.team==s.hero.team and B.dist(u.pos,p)<450 then lit=true end end
        if not lit then risk=risk+0.45 end
        return risk
    end
    function T.safeEngage(s,target)
        if not target or not target.alive or not target.visible or target.invulnerable then return false end
        if s.hero.hpPct<0.43 then return false end
        local a,e=T.balance(s,target.pos,1150)
        -- Do not count an arriving long-distance Charge as a full healthy ally twice.
        if B.dist(s.hero.pos,target.pos)>1150 then a=a+strength(s.hero)*0.75 end
        if e>a*1.08 then return false end
        for _,t in ipairs(s.towers) do
            if t.team~=s.hero.team and B.dist(t.pos,target.pos)<t.range+220 then return false end
        end
        local supporting=0
        for _,u in ipairs(B.near(s.allies,target.pos,900)) do if u.alive and u.hpPct>0.4 then supporting=supporting+1 end end
        -- Several enemies in a matched team fight are not equivalent to being
        -- surrounded alone; numerical/health balance and tower checks still apply.
        return T.at(s,target.pos)<3+math.min(1.5,supporting*0.4)
    end
    function T.retreat(s)
        local origin=s.hero.pos
        local choices={B.toward(origin,B.map.home(s),650)}
        for _,a in ipairs(s.allies) do if a.alive and a.hpPct>0.5 and B.dist(a.pos,origin)<2200 then choices[#choices+1]=B.toward(origin,a.pos,550) end end
        for i=0,7 do local angle=i*math.pi/4 choices[#choices+1]={x=origin.x+math.cos(angle)*650,y=origin.y+math.sin(angle)*650,z=origin.z} end
        local best,score=choices[1],math.huge
        for _,p in ipairs(choices) do
            local walk=B.call('GridNav','IsTraversable',false,B.vec(p))
            if walk then
                local n=T.at(s,p)*1000+B.dist(p,B.map.home(s))*0.02
                for _,t in ipairs(s.towers) do if t.attackTarget==s.hero.index and t.team~=s.hero.team then n=n+math.max(0,t.range+220-B.dist(t.pos,p))*10 end end
                if n<score then best,score=p,n end
            end
        end
        return best
    end
    function T.safety(s)
        if not s.hero.alive then return nil end
        local reason
        for _,t in ipairs(s.towers) do
            if t.team~=s.hero.team and t.attackTarget==s.hero.index and B.dist(t.pos,s.hero.pos)<t.range+300 then reason='Enemy tower targeting hero' break end
        end
        local aggro=0
        for _,c in ipairs(s.creeps) do
            if c.team~=s.hero.team and c.alive and (c.attackTarget==s.hero.index or
                (c.attacking and B.dist(c.pos,s.hero.pos)<c.range+65 and s.hero.recentDamage>20)) then aggro=aggro+1 end
        end
        if s.time<600 and aggro>=3 then reason='Early creep aggro: '..aggro end
        local a,e=T.balance(s,s.hero.pos,900)
        if (s.hero.hpPct<0.27 and e>0) or (e>a*1.55 and s.hero.hpPct<0.65) then reason='Outnumbered / low health' end
        if s.hero.recentDamage>s.hero.maxHp*0.25 and e>0 then reason='Heavy recent damage' end
        if reason then return {name='SAFETY',desire=1.5,reason=reason,pos=T.retreat(s),emergency=true} end
    end
end

end)()
initialize(B)
end

-- MODULE: src/navigation.lua
do
local initialize = (function()
return function(B)
    local N={route={},nextPlan=0} B.navigation=N
    function N.reset() N.route={} N.goal=nil N.nextPlan=0 end
    local function path(a,b)
        local raw=B.call('GridNav','BuildPath',nil,B.vec(a),B.vec(b),false)
        if type(raw)~='table' or #raw==0 then return nil end
        local out={}
        for _,p in ipairs(raw) do local q=B.pos(p) if q then out[#out+1]=q end end
        if #out==0 or B.dist(out[#out],b)>220 then return nil end
        return out
    end
    local function score(s,points,allowTower,escape)
        local cost,prev=0,s.hero.pos
        local initial=B.threat.at(s,prev)
        for _,p in ipairs(points) do
            local length=B.dist(prev,p)
            local count=math.max(1,math.ceil(length/180))
            for i=1,count do
                local q=B.add(prev,B.scale(B.sub(p,prev),i/count))
                local risk=B.threat.at(s,q)
                if not allowTower then
                    for _,t in ipairs(s.towers) do
                        if t.team~=s.hero.team and B.dist(t.pos,q)<t.range+130 then
                            if not escape or B.dist(t.pos,q)<B.dist(t.pos,s.hero.pos)-10 then return math.huge end
                        end
                    end
                end
                cost=cost+length/count*(1+risk*(escape and 0.5 or 1.7))
                if escape and risk>initial+2 then cost=cost+500 end
            end
            prev=p
        end
        return cost
    end
    function N.next(s,destination,allowTower,emergency)
        if not destination or B.dist(s.hero.pos,destination)<70 then N.route={} return nil end
        if s.now>=N.nextPlan or B.dist(destination,N.goal)>180 then
            N.nextPlan=s.now+0.65 N.goal=destination
            local best=path(s.hero.pos,destination)
            local bestScore=best and score(s,best,allowTower,emergency) or math.huge
            if bestScore==math.huge or bestScore>B.dist(s.hero.pos,destination)*2 then
                local dir=B.norm(B.sub(destination,s.hero.pos))
                for _,side in ipairs({-1,1}) do
                    local mid=B.add(B.toward(s.hero.pos,destination,math.min(700,B.dist(s.hero.pos,destination)*0.5)),{x=-dir.y*650*side,y=dir.x*650*side,z=0})
                    local first,second=path(s.hero.pos,mid),path(mid,destination)
                    if first and second then
                        for _,p in ipairs(second) do first[#first+1]=p end
                        local value=score(s,first,allowTower,emergency)
                        if value<bestScore then best,bestScore=first,value end
                    end
                end
            end
            N.route=bestScore<math.huge and best or {}
            if #N.route==0 then B.log('no_route','No safe path; destination deferred',5) end
        end
        while #N.route>0 and B.dist(s.hero.pos,N.route[1])<85 do table.remove(N.route,1) end
        local nextPoint=N.route[1]
        -- Re-evaluate the next segment even when using a cached path.
        if nextPoint and score(s,{nextPoint},allowTower,emergency)<math.huge then return nextPoint end
        return nil
    end
end

end)()
initialize(B)
end

-- MODULE: src/hero.lua
do
local initialize = (function()
-- Decision rules adapted from vendor/OpenHyperAI/bots/BotLib/hero_spirit_breaker.lua:
-- SkillsComplement charge lock; ConsiderChargeOfDarkness interrupts/team balance;
-- ConsiderNetherStrike save modifiers; optional ConsiderPlanarPocket.
-- No Valve bot methods or Action_* orders are used in this adapter-based port.
return function(B)
    local H = {}
    B.hero = H
    local chargeName = 'spirit_breaker_charge_of_darkness'
    local bashName = 'spirit_breaker_greater_bash'
    local bulldozeName = 'spirit_breaker_bulldoze'
    local strikeName = 'spirit_breaker_nether_strike'
    local pocketName = 'spirit_breaker_planar_pocket'

    local function valid(u)
        return u and u.handle and u.pos and u.alive == true
            and u.visible == true and not u.illusion and not u.invulnerable
    end

    local function hasAny(u, names)
        for _, name in ipairs(names) do
            if B.has(u, name) then return true end
        end
        return false
    end

    local protectedMods = {
        'modifier_abaddon_borrowed_time', 'modifier_dazzle_shallow_grave',
        'modifier_oracle_false_promise_timer', 'modifier_oracle_fates_edict',
        'modifier_necrolyte_reapers_scythe', 'modifier_templar_assassin_refraction_absorb',
        'modifier_item_aeon_disk_buff', 'modifier_item_sphere_target',
        'modifier_item_lotus_orb_active', 'modifier_antimage_counterspell',
        'modifier_antimage_spell_shield', 'modifier_faceless_void_chronosphere_freeze',
    }

    local function enemy(s, u)
        -- Immunity piercing is not in CONTRACT.md: conservatively decline immune
        -- targets, even for abilities that may pierce it on a particular patch.
        return valid(u) and u.team ~= nil and u.team ~= s.hero.team
            and not u.magicImmune and not hasAny(u, protectedMods)
    end

    local function flag(value, bit)
        return type(value) == 'number' and math.floor(value / bit) % 2 == 1
    end

    local function ready(s, a, castType, target)
        if not a or not a.handle or a.hidden or a.passive or a.inPhase
            or a.castable ~= true or type(a.level) ~= 'number' or a.level < 1 then
            return false
        end
        -- DOTA_ABILITY_BEHAVIOR_NO_TARGET=4, UNIT_TARGET=8. Metadata is
        -- supplied by the adapter; unknown behavior/range never becomes a guess.
        if not flag(a.behavior, castType == 'none' and 4 or 8) then return false end
        if type(a.manaCost) == 'number' and type(s.hero.mana) == 'number'
            and s.hero.mana < a.manaCost then return false end
        if target then
            return flag(a.targetTeam, 2) and B.inCastRange(a,B.dist(s.hero.pos,target.pos))
        end
        return true
    end

    local function locked(s)
        local h = s.hero
        if not h or not h.alive or h.channeling or h.casting
            or B.has(h, 'modifier_teleporting') then return true end
        for _, a in pairs(s.abilities or {}) do
            if a.inPhase then return true end
        end
        for _, a in pairs(s.items or {}) do
            if a.inPhase then return true end
        end
        return false
    end

    local function cast(a, target, reason, priority)
        return { kind = 'cast', ability = a, target = target,
            castType = target and 'target' or 'none', reason = reason, priority = priority }
    end

    local function distance(a, b)
        return a and b and a.pos and b.pos and B.dist(a.pos, b.pos) or math.huge
    end

    local function hurt(u)
        return (u.recentDamage or 0) > 0 or (u.healthLossRate or 0) > 0
    end

    local function supported(s, target)
        if not B.threat or not B.threat.safeEngage
            or B.threat.safeEngage(s, target) ~= true then return false end
        local allies = 0
        for _, a in ipairs(s.allies or {}) do
            if valid(a) and (a.hpPct or 0) > 0.35 and distance(a, target) < 1100 then
                allies = allies + 1
            end
        end
        -- Support does not start solo global charges or chase into tower range.
        if (s.hero.hpPct or 0) < 0.42 then return false end
        if allies==0 then
            local isolatedFinish=(target.hpPct or 1)<0.18 and (s.hero.hpPct or 0)>0.7 and distance(s.hero,target)<950
            for _,e in ipairs(s.enemies or {}) do if e.index~=target.index and distance(e,target)<1200 then isolatedFinish=false end end
            if not isolatedFinish then return false end
        end
        for _, tower in ipairs(s.towers or {}) do
            if tower.alive and tower.team ~= s.hero.team and tower.pos
                and distance(tower, target) < (tower.range or 800) + 200 then return false end
        end
        return true
    end

    local function towerDanger(s, target)
        for _, tower in ipairs(s.towers or {}) do
            if tower.alive and tower.team ~= s.hero.team and tower.pos
                and distance(tower, target) < (tower.range or 800) + 180 then return true end
        end
        return false
    end

    local function coreReserves(s, target, radius)
        for _, a in ipairs(s.allies or {}) do
            if valid(a) and (a.role == nil or a.role <= 3)
                and distance(a, target) < (radius or 1400) then return true end
        end
        return false
    end

    local function alliedCover(s, target)
        local heroes, creeps = 0, 0
        for _, a in ipairs(s.allies or {}) do
            if valid(a) and (a.hpPct or 0) > 0.4 and distance(a, target) < 1100 then heroes = heroes + 1 end
        end
        for _, c in ipairs(s.creeps or {}) do
            if valid(c) and c.team == s.hero.team and distance(c, target) < 900 then creeps = creeps + 1 end
        end
        return heroes, creeps
    end

    local function mapFightActive(s)
        for _, e in ipairs(s.enemies or {}) do
            if enemy(s, e) then
                for _, a in ipairs(s.allies or {}) do
                    if valid(a) and distance(a, e) < 1100
                        and (a.attackTarget == e.index or e.attackTarget == a.index
                            or (a.recentDamage or 0) > 10 or (e.recentDamage or 0) > 10
                            or a.stunned or e.channeling) then return true end
                end
            end
        end
        return false
    end

    local function baseChargeTarget(s)
        local anchor = valid(s.core) and s.core.pos or B.map.lanePoint(s, s.lane)
        local best, score
        -- A real supported fight is a better exit from base than a creep taxi.
        for _, e in ipairs(s.enemies or {}) do
            if enemy(s, e) and supported(s, e) then
                local value = 1000 + (1 - (e.hpPct or 1)) * 100 - distance(e, {pos=anchor}) / 1000
                if not score or value > score then best, score = e, value end
            end
        end
        if best then return best end
        for _, c in ipairs(s.creeps or {}) do
            local heroes, creeps = alliedCover(s, c)
            if enemy(s, c) and (c.hpPct or 0) > 0.45
                and distance(s.hero, c) > 2500 and not towerDanger(s, c)
                and B.threat.safeEngage(s, c) then
                local value = -distance(c, {pos=anchor}) / 1000 + heroes * 2 + creeps * 0.15
                if not score or value > score then best, score = c, value end
            end
        end
        if best then return best end
        for _, n in ipairs(s.neutrals or {}) do
            local name=n.name or ''
            if enemy(s,n) and (n.hpPct or 0)>0.65 and distance(s.hero,n)>1800
                and not name:find('ancient') and not name:find('roshan') and not name:find('miniboss')
                and not towerDanger(s,n) and B.threat.safeEngage(s,n) then
                local value=-distance(n,{pos=anchor})/1000
                if not score or value>score then best,score=n,value end
            end
        end
        return best
    end

    local function freeFarmChargeTarget(s, mode)
        local modeName = mode and mode.name or ''
        if s.time < 600 or (modeName ~= 'farm' and modeName ~= 'lane' and modeName ~= 'idle'
            and modeName ~= 'group')
            or mapFightActive(s) then return nil end
        for _, e in ipairs(s.enemies or {}) do
            if enemy(s, e) and distance(s.hero, e) < 1800 then return nil end
        end
        local best, score
        local function consider(u, maxDistance)
            local d = distance(s.hero, u)
            if not enemy(s, u) or (u.hpPct or 0) < 0.6 or d < 500 or d > maxDistance
                or towerDanger(s, u) or coreReserves(s, u, 1500)
                or not B.threat.safeEngage(s, u) then return end
            local travel = d / 800
            if (u.hp or 0) - (u.healthLossRate or 0) * travel < (u.maxHp or 1) * 0.3 then return end
            local value = (u.hpPct or 0) * 10 - d / 5000
            if not score or value > score then best, score = u, value end
        end
        for _, c in ipairs(s.creeps or {}) do consider(c, 4500) end
        for _, n in ipairs(s.neutrals or {}) do
            if not (n.name or ''):find('ancient') and not (n.name or ''):find('roshan')
                and not (n.name or ''):find('miniboss') then consider(n, 3000) end
        end
        return best
    end

    local function attackingAlly(s, e)
        if not e.attacking or e.attackTarget == nil then return nil end
        for _, a in ipairs(s.allies or {}) do
            if valid(a) and a.index == e.attackTarget and distance(e, a) < 950
                and ((a.hpPct or 1) < 0.55 or a.channeling) and hurt(a) then return a end
        end
        return nil
    end

    local function offensive(mode)
        local n = mode and mode.name or ''
        return n == 'fight' or n == 'teamfight' or n == 'gank' or n == 'roam'
            or n == 'harass' or n == 'attack' or n == 'defend' or n == 'save'
            or n == 'save_ally' or n == 'protect_core'
    end

    local function retreating(mode)
        local n = mode and mode.name or ''
        return n == 'SAFETY' or n == 'retreat' or n == 'emergency' or n == 'heal' or n == 'fountain'
    end

    function H.consider(s, mode)
        if locked(s) then return nil end
        local h = s.hero
        if h.stunned or h.silenced or h.invulnerable then return nil end
        local abilities = s.abilities or {}
        local charging = B.charging(s)
        local chargeTarget = B.chargeTarget and B.find(s.enemies, B.chargeTarget.index)
        -- Human demonstration: Bulldoze is commonly held until the Charge is
        -- close to connecting. Charge itself must not lock this no-target cast.
        if charging then
            local bulldoze = abilities[bulldozeName]
            local nearArrival = chargeTarget and distance(h, chargeTarget) <= 2400
            local travelled = B.chargeTarget and s.now - B.chargeTarget.issuedAt >= 5
            if ready(s, bulldoze, 'none')
                and not B.has(h, 'modifier_spirit_breaker_bulldoze')
                and (nearArrival or travelled) then
                return cast(bulldoze, nil, 'Bulldoze before Charge impact', 91)
            end
            return nil
        end
        -- Explicit global finisher policy. Before 10:00 it requires more than
        -- half of our health; after 10:00 own HP and the active macro mode do
        -- not block a Charge on an observed low-health enemy.
        if s.time>=600 or (h.hpPct or 0)>0.5 then
            local charge = abilities[chargeName]
            local threshold = (B.config and B.config.lowHpChargeThreshold) or 0.25
            local best, score
            for _, e in ipairs(s.enemies or {}) do
                if enemy(s, e) and (e.hpPct or 1) <= threshold then
                    local value = (1 - (e.hpPct or 1)) * 100 - distance(h, e) / 5000
                    if e.channeling then value = value + 10 end
                    if not score or value > score then best, score = e, value end
                end
            end
            if best and not h.rooted and ready(s, charge, 'target', best) then
                local i = cast(charge, best, 'Global Charge on visible low-health enemy', 95)
                i.lowHpFinisher = true i.forceCharge=true
                return i
            end
        end
        if not retreating(mode) and (h.hpPct or 0) >= 0.78 then
            local charge = abilities[chargeName]
            local tp = (s.items or {}).item_tpscroll
            local atBase = B.map and distance(h, {pos=B.map.home(s)}) <= 1100
            local tpUnavailable = not tp or (tp.charges or 0)<1
                or (type(tp.cooldown) == 'number' and tp.cooldown > 0.1)
            if atBase and tpUnavailable then
                local target = baseChargeTarget(s)
                if target and not h.rooted and ready(s, charge, 'target', target) then
                    local i = cast(charge, target, 'Leave base via Charge while TP is on cooldown', 90)
                    i.baseExitCharge = true
                    return i
                end
            end
        end
        -- Local team fights are independent of the selected walking/warding
        -- mode and of the level-two cross-lane rotation rule.
        if not retreating(mode) and not (mode and mode.name=='gank') and B.support then
            local best,score
            for _,e in ipairs(s.enemies or {}) do
                local intent=B.support.localCharge(s,e)
                if intent and enemy(s,e) and ready(s,intent.ability,'target',e) then
                    local value=(1-e.hpPct)*10+(e.channeling and 20 or 0)-distance(h,e)/1000
                    if not score or value>score then best,score=intent,value end
                end
            end
            if best then return best end
        end
        if mode and mode.name=='gank' and B.support and B.support.canGank(s,mode.target) then
            local a=abilities[chargeName]
            if ready(s,a,'target',mode.target) then
                local i=cast(a,mode.target,'Supported cross-lane Charge from level 2',62)
                i.gank=true return i
            end
        end
        local charge, strike = abilities[chargeName], abilities[strikeName]
        local bulldoze, pocket = abilities[bulldozeName], abilities[pocketName]
        local nearby = 0
        for _, e in ipairs(s.enemies or {}) do
            if valid(e) and distance(h, e) < 850 then nearby = nearby + 1 end
        end

        -- Interrupt channels / peel an observed attacker before ordinary aggression.
        -- Avoid a long-travel "interrupt" and do not interrupt an existing stun.
        for _, e in ipairs(s.enemies or {}) do
            if enemy(s, e) and not e.stunned and supported(s, e) then
                local ally = attackingAlly(s, e)
                if e.channeling or ally then
                    local reason = e.channeling and 'interrupt enemy channel' or 'peel attacker from ally'
                    if not h.rooted and ready(s, strike, 'target', e) then
                        return cast(strike, e, reason, 88)
                    end
                    if not h.rooted and distance(h, e) <= 1000
                        and ready(s, charge, 'target', e) then
                        return cast(charge, e, reason, 86)
                    end
                end
            end
        end

        if ready(s, bulldoze, 'none')
            and not B.has(h, 'modifier_spirit_breaker_bulldoze') and nearby > 0
            and (h.rooted or (hurt(h) and (retreating(mode) or offensive(mode)))) then
            return cast(bulldoze, nil, 'reduce disable duration under pressure', 76)
        end

        -- Planar Pocket can disappear with facet/shard/patch changes. Presence,
        -- training, no-target behavior and observed radius are all required.
        local radius = pocket and pocket.specials and pocket.specials.radius
        if ready(s, pocket, 'none') and type(radius) == 'number' and radius > 0
            and (h.hpPct or 0) > 0.65 and nearby > 0
            and not B.has(h, 'modifier_spirit_breaker_planar_pocket') then
            for _, a in ipairs(s.allies or {}) do
                if valid(a) and distance(h, a) <= radius and (a.hpPct or 1) < 0.5
                    and hurt(a) then
                    return cast(pocket, nil, 'protect nearby injured ally with Planar Pocket', 78)
                end
            end
        end

        if not offensive(mode) or retreating(mode) or h.rooted then
            if not retreating(mode) and not h.rooted and (h.hpPct or 0) >= 0.68 then
                local target = freeFarmChargeTarget(s, mode)
                if target and ready(s, charge, 'target', target) then
                    local i = cast(charge, target, 'Charge a free creep while no fight or team task is active', 48)
                    i.farmCharge = true
                    return i
                end
            end
            return nil
        end
        local best, score
        for _, e in ipairs(s.enemies or {}) do
            if enemy(s, e) and not e.stunned and not e.rooted and supported(s, e)
                and not B.has(e, 'modifier_legion_commander_duel')
                and distance(h, e) <= 1900 then
                local value = (1 - (e.hpPct or 1)) * 20
                    + (mode and mode.target and mode.target.index == e.index and 15 or 0)
                    + (attackingAlly(s, e) and 30 or 0) - distance(h, e) / 200
                if not score or value > score then best, score = e, value end
            end
        end
        if not best then return nil end
        if ready(s, strike, 'target', best) then
            -- No guessed damage/magic-resistance calculation: use Strike for
            -- supported control, not a purported guaranteed magical last hit.
            return cast(strike, best, 'supported Nether Strike on unprotected enemy', 64)
        end
        if distance(h, best) > math.max(350, (h.range or 150) + 100)
            and ready(s, charge, 'target', best) then
            return cast(charge, best, 'short supported Charge initiation', 60)
        end
        return nil
    end

    function H.level(s)
        if locked(s) or not s.hero.handle then return nil end
        -- Verified read-only calls already used by mid_t1_start.lua's LEVEL path.
        -- https://uczone.gitbook.io/api-v2.0/game-components/core/hero
        -- CONTRACT.md has no abilityPoints/upgradeability fields. B.call is the
        -- adapter gateway; nil means unknown, never permission to spend a point.
        local points = B.call('Hero', 'GetAbilityPoints', nil, s.hero.handle)
        if type(points) ~= 'number' or points < 1 then return nil end
        local available, levels = {}, {}
        for name, a in pairs(s.abilities or {}) do
            levels[name] = a.level or 0
            if a.handle and not a.item and not a.hidden and name ~= 'generic_hidden'
                and B.call('Ability', 'CanBeUpgraded', nil, a.handle) == true then
                available[#available + 1] = { name = name, ability = a }
            end
        end
        local function preference(entry)
            local n = entry.name
            -- The recorded pos-4 game opened Bash at level 1 and Charge at
            -- level 2, enabling lane trading first and rotations immediately after.
            if n == bashName and (levels[n] or 0) == 0 then return 130 end
            if n == chargeName and (levels[n] or 0) == 0 then return 125 end
            if n == strikeName then return 115 end
            if n == bulldozeName and (levels[n] or 0) == 0 then return 105 end
            -- Enumerate actual talent names, never hardcode slots/talent IDs.
            -- CanBeUpgraded handles tier requirements, caps and opposite talents.
            if n:match('^special_bonus_') and n ~= 'special_bonus_attributes' then return 100 end
            if n == bashName then return 90 end
            if n == chargeName then return 85 end
            if n == bulldozeName then return 80 end
            if n == 'special_bonus_attributes' then return 10 end
            return 20
        end
        table.sort(available, function(a, b)
            local pa, pb = preference(a), preference(b)
            if pa ~= pb then return pa > pb end
            return a.name < b.name
        end)
        -- As in ability_item_usage_generic.lua AbilityLevelUpComplement, skip
        -- invalid/maxed abilities. Unlike its mutable build cursor, retry against
        -- observed levels so a rejected proposal cannot skip a skill point.
        if available[1] then
            return { kind = 'level', ability = available[1].ability,
                reason = 'level available support skill or valid talent', priority = 15 }
        end
        return nil
    end

    function H.reset() end -- All hero decisions use current observations.
end

end)()
initialize(B)
end

-- MODULE: src/items.lua
do
local initialize = (function()
-- Origins: vendor/OpenHyperAI/bots/ability_item_usage_generic.lua,
-- ItemUsageComplement and ConsiderItemDesire entries for each named item below.
-- Ported principles: cast/channel locks, charged healing, ally saves, facing-aware
-- Force, regen outside combat, grouped smoke and guarded TP. All output is intent.
return function(B)
    local I = {}
    B.items = I
    local pending, owner, lastTime
    local sidePending, restockedAt = nil, -math.huge
    local cleanupAt = -math.huge
    local starter, starterDone, pendingAt, retryAt, inheritedAt
    local function queueCount(s)
        local q=s.quickbuy and s.quickbuy.m_quickBuyItems
        if type(q)~='table' then return nil end
        local n=0 for _,id in pairs(q) do if type(id)=='number' and id>0 and id<65535 then n=n+1 end end
        return n
    end
    local function waiting(s,label,since)
        local n=queueCount(s)
        I.status=label..' | quick-buy '..tostring(n or '?')
        if s.now-(since or s.now)>8 then
            B.log('shop.wait','Waiting for autobuy: '..label..', quick-buy entries='..tostring(n)..', gold='..tostring(s.gold),15)
        end
    end
    local function wardOnlyQueue(s)
        local q=s.quickbuy and s.quickbuy.m_quickBuyItems
        if type(q)~='table' then return false end
        local found=false
        for _,id in pairs(q) do
            if type(id)=='number' and id>0 and id<65535 then
                if id~=42 and id~=43 then return false end
                found=true
            end
        end
        return found
    end

    local function flag(value, bit)
        return type(value) == 'number' and math.floor(value / bit) % 2 == 1
    end
    local function valid(u)
        return u and u.handle and u.pos and u.alive == true
            and u.visible == true and not u.illusion and not u.invulnerable
    end
    local function distance(a, b)
        return a and b and a.pos and b.pos and B.dist(a.pos, b.pos) or math.huge
    end
    local function hasAny(u, names)
        for _, n in ipairs(names) do if B.has(u, n) then return true end end
        return false
    end
    local function hurt(u)
        return (u.recentDamage or 0) > 0 or (u.healthLossRate or 0) > 0
    end
    local function countEnemies(s, u, radius)
        local count = 0
        for _, e in ipairs(s.enemies or {}) do
            if valid(e) and distance(u, e) < radius then count = count + 1 end
        end
        return count
    end
    local function towerAt(s, pos, margin)
        for _, t in ipairs(s.towers or {}) do
            if t.alive and t.team ~= s.hero.team and t.pos
                and B.dist(pos, t.pos) < (t.range or 800) + margin then return true end
        end
        return false
    end
    local function locked(s)
        local h = s.hero
        if not h or not h.alive or h.stunned or h.muted or h.invulnerable
            or h.channeling or h.casting or B.has(h, 'modifier_teleporting')
            or B.has(h, 'modifier_spirit_breaker_charge_of_darkness') then return true end
        for _, a in pairs(s.abilities or {}) do if a.inPhase then return true end end
        for _, a in pairs(s.items or {}) do if a.inPhase then return true end end
        return false
    end
    local function ready(s, name, castType, target)
        local a = (s.items or {})[name]
        if not a or not a.handle or a.castable ~= true or a.hidden or a.passive or a.inPhase then return nil end
        -- Backpack/stash items cannot be activated. TP/neutral dedicated slots
        -- match ItemUsageComplement's 0..5,15,16 scan; unknown slot is not usable.
        if type(a.slot) ~= 'number' or not ((a.slot >= 0 and a.slot <= 5)
            or a.slot == 15 or a.slot == 16) then return nil end
        local bit = castType == 'target' and 8 or (castType == 'position' and 16 or 4)
        if not flag(a.behavior, bit) then return nil end
        if type(a.manaCost) == 'number' and type(s.hero.mana) == 'number'
            and s.hero.mana < a.manaCost then return nil end
        if target then
            if not valid(target) then return nil end
            local teamBit = target.team == s.hero.team and 1 or 2
            if not flag(a.targetTeam, teamBit) then return nil end
            if target.index ~= s.hero.index and (type(a.range) ~= 'number'
                or a.range <= 0 or distance(s.hero, target) > a.range) then return nil end
        end
        return a
    end
    local function cast(a, target, reason, priority, pos)
        return { kind = 'cast', ability = a, target = target, pos = pos,
            castType = pos and 'position' or (target and 'target' or 'none'),
            reason = reason, priority = priority }
    end
    local function threatened(s, u)
        return countEnemies(s, u, 900) > 0 and (hurt(u) or u.stunned or u.rooted or u.silenced)
    end
    local function quiet(s, u)
        -- Unknown damage history is not evidence of uninterrupted regen.
        return type(u.recentDamage) == 'number' and u.recentDamage <= 2
            and type(u.healthLossRate) == 'number' and u.healthLossRate <= 1
            and countEnemies(s, u, 1100) == 0 and not towerAt(s, u.pos, 100)
            and not B.has(u, 'modifier_fountain_aura_buff')
            and not B.has(u, 'modifier_fountain_aura')
    end
    local function missing(u, resource)
        local current, maximum = u[resource], u[resource == 'hp' and 'maxHp' or 'maxMana']
        if type(current) ~= 'number' or type(maximum) ~= 'number' then return 0 end
        return maximum - current
    end

    local function forceSafe(s, ally, item)
        if ally.channeling or ally.casting or ally.magicImmune
            or B.has(ally, 'modifier_teleporting')
            or B.has(ally, 'modifier_spirit_breaker_charge_of_darkness') then return false end
        -- CONTRACT.facing must be an observed forward {x,y,z}, not an angle with
        -- guessed units. Missing/ambiguous direction or push length => no Force.
        local facing = ally.facing
        local length = item.specials and item.specials.push_length
        if type(facing) ~= 'table' or type(facing.x) ~= 'number' or type(facing.y) ~= 'number'
            or type(length) ~= 'number' or length <= 0 then return false end
        local magnitude = math.sqrt(facing.x * facing.x + facing.y * facing.y)
        if magnitude < 0.01 or not B.threat or not B.threat.at then return false end
        local finish = B.add(ally.pos, { x = facing.x / magnitude * length,
            y = facing.y / magnitude * length, z = 0 })
        local before, after = B.threat.at(s, ally.pos), B.threat.at(s, finish)
        if type(before) ~= 'number' or type(after) ~= 'number' or after >= before then return false end
        if towerAt(s, finish, 200) then return false end
        -- Reject pushes through a more dangerous corridor, not just bad endpoints.
        for step = 1, 3 do
            local risk = B.threat.at(s, B.toward(ally.pos, finish, length * step / 4))
            if type(risk) ~= 'number' or risk > before then return false end
        end
        return true
    end

    local invisMods = {
        'modifier_invisible', 'modifier_riki_permanent_invisibility',
        'modifier_bounty_hunter_wind_walk', 'modifier_clinkz_wind_walk',
        'modifier_nyx_assassin_vendetta', 'modifier_weaver_shukuchi',
        'modifier_item_invisibility_edge_windwalk', 'modifier_item_silver_edge_windwalk',
        'modifier_item_glimmer_cape', 'modifier_invoker_ghost_walk_self',
    }
    local revealMods = { 'modifier_item_dustofappearance', 'modifier_slardar_amplify_damage',
        'modifier_bounty_hunter_track' }
    local saveMods = { 'modifier_abaddon_borrowed_time', 'modifier_dazzle_shallow_grave',
        'modifier_oracle_false_promise_timer', 'modifier_oracle_fates_edict',
        'modifier_item_aeon_disk_buff', 'modifier_item_sphere_target',
        'modifier_item_lotus_orb_active', 'modifier_antimage_counterspell' }
    local healMods = { 'modifier_item_urn_heal', 'modifier_item_spirit_vessel_heal',
        'modifier_flask_healing', 'modifier_tango_heal',
        'modifier_fountain_aura', 'modifier_fountain_aura_buff' }

    function I.consider(s, mode)
        if locked(s) then return nil end
        local h, n = s.hero, mode and mode.name or ''
        local enemies = countEnemies(s, h, 900)
        local retreat = n == 'SAFETY' or n == 'retreat' or n == 'emergency' or n == 'heal' or n == 'fountain'
        local fight = n == 'fight' or n == 'teamfight' or n == 'attack' or n == 'gank'
            or n == 'harass' or n == 'defend' or n == 'save' or n == 'save_ally' or n == 'protect_core'

        -- Faerie Fire is an emergency combat heal, not disposable starter clutter.
        -- Use it before the incoming damage can finish the hero; do not waste it
        -- merely because some health is missing outside combat.
        local faerie = ready(s, 'item_faerie_fire', 'none')
        if faerie and (faerie.charges or 0) > 0 and enemies > 0 and hurt(h)
            and ((h.hpPct or 1) <= 0.28 or (h.healthLossRate or 0) >= math.max(45,(h.hp or 0)*0.18)) then
            return cast(faerie, nil, 'Emergency Faerie Fire while taking lethal pressure', 97)
        end

        for _, name in ipairs({ 'item_magic_wand', 'item_magic_stick' }) do
            local a = ready(s, name, 'none')
            if a and (a.charges or 0) > 0 and (missing(h, 'hp') > 0 or missing(h, 'mana') > 0)
                and ((enemies > 0 and ((h.hpPct or 1) < 0.5 or (h.manaPct or 1) < 0.3))
                    or ((h.hpPct or 1) < 0.3 and hurt(h))) then
                return cast(a, nil, 'restore health/mana with observed stick charges', 94)
            end
        end
        local bkb = ready(s, 'item_black_king_bar', 'none')
        if bkb and enemies > 0 and not h.magicImmune
            and not B.has(h, 'modifier_black_king_bar_immune')
            and (h.rooted or h.silenced or (hurt(h) and (h.hpPct or 1) < 0.55 and (fight or retreat))) then
            return cast(bkb, nil, 'BKB against immediate disable/damage pressure', 92)
        end

        local allies = { h }
        for _, a in ipairs(s.allies or {}) do if valid(a) then allies[#allies + 1] = a end end
        table.sort(allies, function(a, b)
            local av = (a.hpPct or 1) - ((a.role or 5) <= 3 and 0.08 or 0)
            local bv = (b.hpPct or 1) - ((b.role or 5) <= 3 and 0.08 or 0)
            return av < bv
        end)
        for _, ally in ipairs(allies) do
            if valid(ally) and threatened(s, ally) then
                local force = ready(s, 'item_force_staff', 'target', ally)
                if force and (ally.hpPct or 1) < 0.5 and forceSafe(s, ally, force) then
                    return cast(force, ally, 'Force ally toward observed lower threat', 90)
                end
                local glimmer = ready(s, 'item_glimmer_cape', 'target', ally)
                if glimmer and (ally.hpPct or 1) < 0.55 and not ally.magicImmune
                    and not B.has(ally, 'modifier_item_glimmer_cape')
                    and not hasAny(ally, revealMods) and not towerAt(s, ally.pos, 100) then
                    return cast(glimmer, ally, 'Glimmer injured ally under pressure', 89)
                end
                local lotus = ready(s, 'item_lotus_orb', 'target', ally)
                if lotus and not B.has(ally, 'modifier_item_lotus_orb_active')
                    and not ally.magicImmune and (ally.rooted or ally.silenced or ally.disarmed) then
                    return cast(lotus, ally, 'Lotus dispel for pressured ally', 88)
                end
            end
        end

        local dust = ready(s, 'item_dust', 'none')
        local dustRadius = dust and dust.specials and dust.specials.radius
        if dust and (dust.charges or 0) > 0 and type(dustRadius) == 'number' and dustRadius > 0 then
            for _, e in ipairs(s.enemies or {}) do
                if valid(e) and distance(h, e) <= dustRadius and hasAny(e, invisMods)
                    and not hasAny(e, revealMods) then
                    return cast(dust, nil, 'reveal observed nearby invisibility', 82)
                end
            end
        end

        for _, name in ipairs({ 'item_spirit_vessel', 'item_urn_of_shadows' }) do
            for _, ally in ipairs(allies) do
                local a = ready(s, name, 'target', ally)
                if a and (a.charges or 0) > 0 and missing(ally, 'hp') > 400
                    and quiet(s, ally) and not hasAny(ally, healMods) then
                    return cast(a, ally, 'heal ally between fights with urn/vessel', 55)
                end
            end
            local target = mode and mode.target
            local a = target and ready(s, name, 'target', target)
            if a and fight and (a.charges or 0) > 0 and target.team ~= h.team
                and not target.magicImmune and not hasAny(target, saveMods)
                and not B.has(target, 'modifier_item_urn_damage')
                and not B.has(target, 'modifier_item_spirit_vessel_damage')
                and (target.hpPct or 1) < 0.9 then
                return cast(a, target, 'urn/vessel pressure on unprotected fight target', 54)
            end
        end

        local phase = ready(s, 'item_phase_boots', 'none')
        local destination = mode and (mode.pos or (mode.target and mode.target.pos))
        if phase and not h.rooted and not B.has(h, 'modifier_item_phase_boots_active')
            and ((retreat and enemies > 0) or (destination and B.dist(h.pos, destination) > 400
                and (not h.attacking or fight))) then
            return cast(phase, nil, 'Phase movement toward current objective', 45)
        end

        -- Tango is tree-targeted rather than hero-targeted. The adapter exposes
        -- only nearby observed trees, and the executor validates the tree handle
        -- and cast range before issuing the order.
        if (h.hpPct or 1) < 0.78 and missing(h, 'hp') > 140
            and not hasAny(h, healMods) and countEnemies(s, h, 650) == 0
            and not B.has(h, 'modifier_fountain_aura_buff') then
            local tango = (s.items or {}).item_tango or (s.items or {}).item_tango_single
            if tango and tango.handle and tango.castable == true and not tango.hidden
                and not tango.passive and not tango.inPhase and (tango.charges or 0) > 0 then
                local tree, best = nil, math.huge
                for _, candidate in ipairs(s.trees or {}) do
                    local d = candidate and candidate.pos and B.dist(h.pos, candidate.pos) or math.huge
                    if candidate and candidate.handle and d < best and d <= (tango.range or 0) + 25 then
                        tree, best = candidate, d
                    end
                end
                if tree then return {kind='cast', ability=tango, castType='tree', target=tree,
                    reason='Use Tango on an observed nearby tree for lane sustain', priority=36} end
            end
        end

        for _, ally in ipairs(allies) do
            if valid(ally) and quiet(s, ally) then
                local flask = ready(s, 'item_flask', 'target', ally)
                if flask and (flask.charges or 0) > 0 and missing(ally, 'hp') > 450
                    and not hasAny(ally, healMods) then
                    return cast(flask, ally, 'safe healing salve between fights', 35)
                end
                local clarity = ready(s, 'item_clarity', 'target', ally)
                if clarity and (clarity.charges or 0) > 0 and missing(ally, 'mana') > 250
                    and (ally.manaPct or 1) < 0.4 and not B.has(ally, 'modifier_clarity_potion') then
                    return cast(clarity, ally, 'safe mana regeneration between fights', 34)
                end
            end
        end

        local smoke = ready(s, 'item_smoke_of_deceit', 'none')
        local radius = smoke and smoke.specials and smoke.specials.application_radius
        if smoke and (smoke.charges or 0) > 0 and type(radius) == 'number' and radius > 0
            and (n == 'gank' or n == 'roam' or n == 'roshan') and destination
            and B.dist(h.pos, destination) > 1800 and not B.has(h, 'modifier_smoke_of_deceit') then
            local grouped, safe = 0, true
            for _, ally in ipairs(allies) do
                if distance(h, ally) <= radius then
                    if countEnemies(s, ally, 1400) > 0 or towerAt(s, ally.pos, 600)
                        or hurt(ally) or ally.channeling or (ally.hpPct or 0) < 0.6 then safe = false end
                    if ally.index ~= h.index and not B.has(ally, 'modifier_smoke_of_deceit') then
                        grouped = grouped + 1
                    end
                end
            end
            if safe and grouped >= 2 then return cast(smoke, nil, 'smoke healthy group for planned rotation', 30) end
        end

        local tp = ready(s, 'item_tpscroll', 'position')
        if tp and (tp.charges or 0) > 0 and retreat and not h.rooted and quiet(s, h)
            and ((h.hpPct or 1) < 0.3 or ((h.manaPct or 1) < 0.15 and (h.hpPct or 1) < 0.6))
            and not B.has(h, 'modifier_kunkka_x_marks_the_spot') then
            local home = B.map and B.map.home and B.map.home(s)
            if home and B.dist(h.pos, home) > 3500 then
                return cast(tp, nil, 'safe fountain TP to recover', 40, home)
            end
        end
        return nil
    end

    -- Keep important usable items out of backpack. If all six active slots are
    -- occupied, discard obsolete cheap clutter first; boots and Tango are never
    -- discarded. Manipulation is deferred while enemies or damage are nearby.
    function I.cleanup(s)
        if not s or not s.hero or type(s.inventory)~='table' or s.now-cleanupAt<1.5 then return nil end
        if s.hero.recentDamage>0 or countEnemies(s,s.hero,1400)>0 or s.hero.channeling or s.hero.casting then return nil end
        local active,used,backpack={},{},{}
        for _,item in ipairs(s.inventory) do
            if type(item.slot)=='number' and item.slot>=0 and item.slot<=5 then
                active[#active+1]=item used[item.slot]=true
            elseif type(item.slot)=='number' and item.slot>=6 and item.slot<=8 then
                backpack[#backpack+1]=item
            end
        end
        local importance={
            item_boots=100,item_phase_boots=100,item_tranquil_boots=100,
            item_power_treads=100,item_arcane_boots=100,item_guardian_greaves=100,
            item_boots_of_bearing=100,item_travel_boots=100,item_travel_boots_2=100,
            item_invis_sword=96,item_silver_edge=98,
            item_yasha_and_kaya=90,item_cyclone=92,item_wind_waker=97,
            item_black_king_bar=99,item_lotus_orb=95,item_force_staff=94,
            item_glimmer_cape=94,item_spirit_vessel=93,item_urn_of_shadows=82,
            item_blade_mail=88,item_aeon_disk=96,item_shivas_guard=91,
            item_sphere=96,item_octarine_core=90,item_ultimate_scepter=89,
            item_magic_wand=84,item_dust=78,item_smoke_of_deceit=76,
            item_ward_observer=74,item_ward_sentry=74,item_ward_dispenser=75,
            item_faerie_fire=72,item_tango=70,item_flask=68,item_clarity=64,
        }
        local function itemImportance(item)
            return importance[item.name]
                or ((item.cost or 0)>=800 and 60+(item.cost or 0)/1000 or 20+(item.cost or 0)/1000)
        end
        local important,importantScore
        for _,item in ipairs(backpack) do
            local score=itemImportance(item)
            if score<60 then score=nil end
            if score and (not importantScore or score>importantScore) then important,importantScore=item,score end
        end
        if important and #active<6 then
            local slot
            for n=0,5 do if not used[n] then slot=n break end end
            if slot~=nil then
                cleanupAt=s.now
                return {kind='move_item',item=important,destinationSlot=slot,
                    reason='Move important backpack item into active inventory: '..important.name,priority=12}
            end
        end
        if #active<6 then return nil end
        local phase=type(s.ownedItems)=='table' and (s.ownedItems.item_phase_boots or 0)>0
        local rank={item_branches=1,item_faerie_fire=2,item_wind_lace=3}
        local best,bestRank
        for _,item in ipairs(active) do
            local r=rank[item.name]
            local allowed=r==1 and (important~=nil or s.time>=600)
                or r==2 and s.time>=900
                or r==3 and phase
            if allowed and item.droppable==true and not (item.name or ''):find('boots',1,true)
                and (not bestRank or r<bestRank) then best,bestRank=item,r end
        end
        if best then
            cleanupAt=s.now
            return {kind='drop',item=best,pos=B.toward(s.hero.pos,B.map.home(s),80),
                reason='Drop obsolete cheap slot blocker: '..best.name,priority=10}
        end
        if important then
            local replace,replaceScore
            for _,item in ipairs(active) do
                local score=itemImportance(item)
                if not (item.name or ''):find('boots',1,true)
                    and (not replaceScore or score<replaceScore) then replace,replaceScore=item,score end
            end
            if replace and importantScore>replaceScore+5 then
                cleanupAt=s.now
                return {kind='move_item',item=important,destinationSlot=replace.slot,swap=true,
                    reason='Swap important backpack item with lower-priority active item',priority=11}
            end
        end
        return nil
    end

    local healingHeroes = { npc_dota_hero_huskar = true, npc_dota_hero_alchemist = true,
        npc_dota_hero_necrolyte = true, npc_dota_hero_morphling = true,
        npc_dota_hero_dazzle = true, npc_dota_hero_oracle = true,
        npc_dota_hero_witch_doctor = true, npc_dota_hero_leshrac = true }
    local invisHeroes = { npc_dota_hero_riki = true, npc_dota_hero_bounty_hunter = true,
        npc_dota_hero_clinkz = true, npc_dota_hero_nyx_assassin = true,
        npc_dota_hero_weaver = true, npc_dota_hero_invoker = true }
    local upgrades = {
        item_boots = { 'item_phase_boots', 'item_tranquil_boots', 'item_power_treads',
            'item_arcane_boots', 'item_guardian_greaves', 'item_boots_of_bearing',
            'item_travel_boots', 'item_travel_boots_2' },
        item_magic_stick = { 'item_magic_wand', 'item_holy_locket' },
        item_magic_wand = { 'item_holy_locket' },
        item_urn_of_shadows = { 'item_spirit_vessel' },
        item_force_staff = { 'item_hurricane_pike' },
        item_invis_sword = { 'item_silver_edge' },
        item_cyclone = { 'item_wind_waker' },
    }
    local function owned(s, name)
        local quantity = (s.ownedItems or {})[name]
        return type(quantity) == 'number' and quantity > 0
    end
    local function satisfied(s, name)
        if owned(s, name) then return true end
        if name == 'item_aghanims_shard' and B.has(s.hero, 'modifier_item_aghanims_shard') then return true end
        if name == 'item_ultimate_scepter' and B.has(s.hero, 'modifier_item_ultimate_scepter_consumed') then return true end
        if name == 'item_moon_shard' and B.has(s.hero, 'modifier_item_moon_shard_consumed') then return true end
        for _, upgrade in ipairs(upgrades[name] or {}) do
            if owned(s, upgrade) then return true end
        end
        return false
    end

    function I.purchase(s)
        if not s.hero or not s.hero.handle or type(s.ownedItems) ~= 'table' then return nil end
        local now = s.now
        if owner ~= s.hero.handle or (type(now) == 'number' and lastTime and now < lastTime) then I.reset() end
        owner, lastTime = s.hero.handle, now
        if B.executor and B.executor.quickbuyJob then return nil end
        -- User-defined Spirit Breaker opening. Keep it exact and deterministic;
        -- support consumables are replenished independently after this queue.
        if not starterDone and not starter then
            if s.time>=600 or satisfied(s,'item_boots') then starterDone=true
            elseif (queueCount(s) or 0)>0 and not wardOnlyQueue(s) then
                inheritedAt=inheritedAt or now
                waiting(s,'existing queue retained',inheritedAt)
                return nil
            else
                local names,required={},{}
                for _,entry in ipairs({{'item_wind_lace',1},{'item_branches',2},
                    {'item_tango',1},{'item_faerie_fire',1}}) do
                    local name,count=entry[1],entry[2]
                    local have=s.ownedItems[name] or 0
                    if have<count then required[name]=count
                        for _=have+1,count do names[#names+1]=name end
                    end
                end
                if #names>0 then
                    starter={required=required,seen={},since=now,names=names}
                    I.status='starting kit queued'
                    return {kind='quickbuy',itemNames=names,itemName=names[1],reset=true,
                        reason='Spirit Breaker start: Wind Lace, two Branches, Tango, Faerie Fire'}
                end
                starterDone=true
            end
        end
        if starter then
            local complete=true
            for name,count in pairs(starter.required) do
                if (s.ownedItems[name] or 0)>=count then starter.seen[name]=true end
                if not starter.seen[name] then complete=false end
            end
            if complete then starter=nil starterDone=true
            else
                waiting(s,'starting kit awaiting purchase',starter.since)
                if queueCount(s)==0 and now-starter.since>3 and now-(retryAt or -100)>5 then
                    retryAt=now
                    local missing={}
                    for _,entry in ipairs({{'item_wind_lace',1},{'item_branches',2},
                        {'item_tango',1},{'item_faerie_fire',1}}) do
                        if starter.required[entry[1]] and not starter.seen[entry[1]] then
                            for _=(s.ownedItems[entry[1]] or 0)+1,entry[2] do missing[#missing+1]=entry[1] end
                        end
                    end
                    if #missing>0 then return {kind='quickbuy',itemNames=missing,itemName=missing[1],reset=true,reason='Restore empty starting queue'} end
                end
                return nil
            end
        end
        if sidePending and owned(s,sidePending) then sidePending=nil end
        -- Ward IDs are public metadata from Umbrella assets/data/items.json.
        -- Never erase a partly purchased major item to replenish consumables.
        local hasWard=owned(s,'item_ward_observer') or owned(s,'item_ward_sentry') or owned(s,'item_ward_dispenser')
        local observerStock=B.call('Item','GetStockCount',nil,42,s.hero.team)
        if satisfied(s,'item_phase_boots') and not hasWard and not sidePending and now-restockedAt>180
            and type(observerStock)=='number' and observerStock>0 then
            sidePending='item_ward_observer'; restockedAt=now
            return {kind='quickbuy',itemName=sidePending,reset=pending==nil,
                reason='Restock support observer without discarding the major item queue',priority=6}
        end
        if sidePending and not pending then
            -- The optional ward gets a bounded wait, never blocks boots forever.
            if now-restockedAt<3 then return nil end
            sidePending=nil
        end
        if pending then
            if not satisfied(s, pending) then
                waiting(s,pending,pendingAt)
                if queueCount(s)==0 and now-(pendingAt or now)>3 and now-(retryAt or -100)>5 then
                    retryAt=now
                    return {kind='quickbuy',itemName=pending,reset=true,reason='Restore lost empty quick-buy queue'}
                end
                return nil
            end
            pending = nil
        end
        local antiheal, detection, pressure = false, false, 0
        for _, e in ipairs(s.enemies or {}) do
            if valid(e) then
                antiheal = antiheal or healingHeroes[e.name] or false
                detection = detection or invisHeroes[e.name] or hasAny(e, invisMods)
                if e.casting or e.channeling then pressure = pressure + 1 end
            end
        end
        local wanted = {}
        local function want(name, condition)
            if condition ~= false and not satisfied(s, name) then wanted[#wanted + 1] = name end
        end
        -- Stable core requested for Spirit Breaker. Each goal remains pending
        -- until it is observed on hero/courier, so autobuy cannot skip ahead.
        if not satisfied(s, 'item_boots') then want('item_boots')
        elseif not satisfied(s, 'item_phase_boots') then want('item_phase_boots')
        elseif not satisfied(s, 'item_invis_sword') then want('item_invis_sword')
        end
        local needsDispel = s.hero.rooted or s.hero.silenced
        for _, a in ipairs(s.allies or {}) do
            if valid(a) and (a.rooted or a.silenced) then needsDispel = true end
        end
        local branchDone = satisfied(s, 'item_yasha_and_kaya') or satisfied(s, 'item_cyclone')
        if satisfied(s, 'item_invis_sword') and not branchDone then
            -- Eul is the defensive/control branch; Yasha & Kaya is the default.
            want((needsDispel or pressure >= 2) and 'item_cyclone' or 'item_yasha_and_kaya')
        elseif branchDone and not satisfied(s, 'item_silver_edge') then
            want('item_silver_edge')
        end

        -- Situational pool from the supplied build, evaluated only after the
        -- core. Observable danger selects defensive utility; otherwise scale
        -- Charge/Bash with shard, Aghanim, Octarine and late movement speed.
        local coreDone = branchDone and satisfied(s, 'item_silver_edge')
        if coreDone then
            want('item_black_king_bar', pressure >= 2 or (needsDispel and hurt(s.hero)))
            want('item_lotus_orb', needsDispel)
            want('item_spirit_vessel', antiheal)
            want('item_dust', detection)
            want('item_blade_mail', pressure >= 2 and (s.hero.hpPct or 1) < 0.7)
            want('item_aeon_disk', pressure >= 3 and (s.hero.hpPct or 1) < 0.55)
            want('item_aghanims_shard', type(s.time)=='number' and s.time >= 900)
            want('item_ultimate_scepter')
            want('item_wind_waker', satisfied(s, 'item_cyclone') and needsDispel)
            want('item_shivas_guard', pressure >= 2)
            want('item_sphere', needsDispel)
            want('item_octarine_core')
            want('item_travel_boots', type(s.time)=='number' and s.time >= 2400)
            want('item_moon_shard', type(s.time)=='number' and s.time >= 2700)
        end
        -- Queue smoke only once core save tools are owned, with a grouped team.
        local grouped = 0
        for _, a in ipairs(s.allies or {}) do
            if valid(a) and distance(a, s.hero) < 1000 then grouped = grouped + 1 end
        end
        want('item_smoke_of_deceit', grouped >= 2)
        if wanted[1] then
            pending = wanted[1]
            pendingAt=now I.status='queued '..pending
            -- Record only a PROPOSAL, never assumed purchase success. No elapsed
            -- timeout advances/reissues it: that would overwrite a partially
            -- bought component queue. Completion is observed across inventory,
            -- stash and courier via ownedItems. CONTRACT has no quickbuy receipt;
            -- after a rejected queue proposal, the coordinator can call reset()
            -- to retry. Executor alone sets quickbuy; this is not auto-purchase.
            return { kind = 'quickbuy', itemName = pending,
                reason = 'support purchase goal; retain until ownership observed', priority = 5 }
        end
        return nil
    end

    function I.reset()
        pending, owner, lastTime = nil, nil, nil
        sidePending, restockedAt = nil, -math.huge
        starter,starterDone,pendingAt,retryAt,inheritedAt=nil,false,nil,nil,nil
        cleanupAt=-math.huge
        I.status='initializing'
    end
end

end)()
initialize(B)
end

-- MODULE: src/support.lua
do
local initialize = (function()
-- Active support decisions. Goals are stable; the executor owns every order.
return function(B)
    local S={} B.support=S
    local patrol, trade, gank, lastGank, wardAttempt
    function S.reset() patrol=nil trade=nil gank=nil lastGank=-100 wardAttempt={} end
    S.reset()
    local function alive(u) return u and u.alive and not u.illusion end
    local function enemy(s,u) return alive(u) and u.visible and u.team~=s.hero.team and not u.invulnerable end
    local function towerDanger(s,p,margin)
        for _,t in ipairs(s.towers) do if t.alive and t.team~=s.hero.team and B.dist(t.pos,p)<t.range+(margin or 160) then return true end end
        return false
    end
    local function creepsAt(s,p)
        local n=0
        for _,c in ipairs(s.creeps) do if enemy(s,c) and B.dist(c.pos,p)<c.range+90 then n=n+1 end end
        return n
    end
    local function counts(s,p,r)
        local a=B.dist(s.hero.pos,p)<r and 1 or 0
        local e=0
        for _,u in ipairs(B.near(s.allies,p,r)) do if alive(u) then a=a+1 end end
        for _,u in ipairs(B.near(s.enemies,p,r)) do if enemy(s,u) then e=e+1 end end
        return a,e
    end
    local function move(s,p,reason)
        if not p or s.hero.rooted or B.dist(s.hero.pos,p)<65 or towerDanger(s,p) then return nil end
        local risk=B.threat.at(s,p)
        if risk>math.max(2.4,B.threat.at(s,s.hero.pos)+0.25) then return nil end
        if not B.call('GridNav','IsTraversable',false,B.vec(p)) then return nil end
        return {kind='move',pos=p,reason=reason}
    end
    local function offer(out,name,desire,intent,target,key)
        if intent then out[#out+1]={name=name,desire=desire,intent=intent,target=target,pos=intent.pos,
            reason=intent.reason,key=key or name..':'..tostring(target and target.index or '')} end
    end
    function S.coreDanger(s)
        local c=s.core
        if not alive(c) then return false end
        local _,foes=counts(s,c.pos,950)
        return foes>0 and (c.hpPct<0.65 or c.recentDamage>35 or c.stunned or foes>=2)
    end
    function S.localFight(s,e)
        if not enemy(s,e) or B.dist(s.hero.pos,e.pos)>1400 then return false end
        for _,a in ipairs(B.near(s.allies,e.pos,800)) do
            if alive(a) and (a.recentDamage>10 or a.attackTarget==e.index or e.attackTarget==a.index
                or (a.attacking and e.recentDamage>0 and B.dist(a.pos,e.pos)<a.range+150)
                or ((a.channeling or a.casting) and B.dist(a.pos,e.pos)<400)
                or (e.recentDamage>10 and B.dist(a.pos,e.pos)<600)
                or B.has(a,'modifier_juggernaut_blade_fury')) then return true end
        end
        return false
    end
    function S.localCharge(s,e)
        local a=s.abilities.spirit_breaker_charge_of_darkness
        if not S.localFight(s,e) then return nil,'no nearby allied fight' end
        if not a or a.level<1 or not a.castable then return nil,'Charge not ready' end
        if s.hero.rooted or s.hero.silenced or s.hero.hpPct<0.43 then return nil,'hero disabled or low health' end
        if e.magicImmune or B.has(e,'modifier_item_sphere_target') or B.has(e,'modifier_item_lotus_orb_active') then return nil,'protected target' end
        if not B.threat.safeEngage(s,e) then return nil,'unsafe local engagement' end
        local d=B.dist(s.hero.pos,e.pos)
        if d<math.max(220,s.hero.range+40) and not e.channeling then return nil,'already in attack range' end
        local steps=math.max(1,math.ceil(d/200))
        for n=1,steps do
            if towerDanger(s,B.add(s.hero.pos,B.scale(B.sub(e.pos,s.hero.pos),n/steps)),120) then return nil,'tower on Charge path' end
        end
        return {kind='cast',ability=a,castType='target',target=e,reason='Join nearby allied fight with Charge',priority=85}
    end
    local function laneTradeSetup(s,e)
        local c=s.core
        if s.time>=600 or not alive(c) or not enemy(s,e) then return false end
        if s.hero.hpPct<0.72 or c.hpPct<0.62 or s.hero.recentDamage>35 then return false end
        if B.dist(s.hero.pos,c.pos)>850 or B.dist(c.pos,e.pos)>700 or towerDanger(s,e.pos) then return false end
        local allies,foes=counts(s,e.pos,1000)
        local landing=B.toward(e.pos,s.hero.pos,math.max(90,s.hero.range-20))
        return allies>=foes and creepsAt(s,landing)<=2
    end
    local function patrolIntent(s)
        local anchor=B.map.coreOnLane(s,s.core) and B.toward(s.core.pos,B.map.home(s),260) or B.map.lanePoint(s,s.lane)
        if B.dist(s.hero.pos,anchor)>650 then return move(s,anchor,'Move into support range on the assigned lane') end
        if patrol and s.now<patrol.untilTime and B.dist(s.hero.pos,patrol.pos)>90 and B.dist(patrol.anchor,anchor)<250 then
            local i=move(s,patrol.pos,'Reposition along the safe side of the wave') if i then return i end
        end
        local rear=B.norm(B.sub(B.map.home(s),anchor))
        local side={x=-rear.y,y=rear.x,z=0}
        local best,score=nil,math.huge
        for _,sign in ipairs({-1,1}) do
            for _,back in ipairs({0,180}) do
                local p=B.add(B.add(anchor,B.scale(side,sign*230)),B.scale(rear,back))
                local d=B.dist(s.hero.pos,p)
                if d>120 and creepsAt(s,p)<3 and move(s,p,'patrol check') then
                    local risk=B.threat.at(s,p)*1000+d*0.15
                    if risk<score then best,score=p,risk end
                end
            end
        end
        if best then patrol={pos=best,anchor=anchor,untilTime=s.now+3.5}; return move(s,best,'Reposition along the safe side of the wave') end
    end
    local function trades(out,s)
        if trade then
            local target=B.find(s.enemies,trade.index)
            if not enemy(s,target) then trade=nil
            else
                local allies,foes=counts(s,target.pos,1000)
                local ownLoss=(trade.startHpPct or s.hero.hpPct)-s.hero.hpPct
                local enemyLoss=(trade.targetHpPct or target.hpPct)-target.hpPct
                local bad=s.now>=trade.expires or s.hero.hpPct<0.58 or s.hero.recentDamage>55
                    or foes>allies or creepsAt(s,s.hero.pos)>=3 or towerDanger(s,target.pos)
                    or (trade.hits>=1 and ownLoss>math.max(0.07,enemyLoss+0.04))
                    or trade.hits>=3
                if bad then
                    trade.resetUntil=trade.resetUntil or (s.now+1.25)
                    if s.now<trade.resetUntil then
                        offer(out,'trade_reset',0.74,move(s,B.threat.retreat(s),
                            'Disengage after completed or unfavorable lane trade'),target,'trade_reset:'..target.index)
                        return
                    end
                    trade=nil
                else
                    local d=B.dist(s.hero.pos,target.pos)
                    local i
                    if d<=s.hero.range+35 and not s.hero.disarmed then
                        i={kind='attack',target=target,reason='Continue profitable lane trade',tradeContinue=true}
                    elseif d<1100 then
                        local landing=B.toward(target.pos,s.hero.pos,math.max(90,s.hero.range-20))
                        i=move(s,landing,'Keep closing distance for the active lane trade')
                    end
                    if i then
                        i.tradeIndex=target.index
                        offer(out,'harass',0.66,i,target,'support_trade:'..target.index)
                        return
                    end
                    trade=nil
                end
            end
        end
        for _,e in ipairs(s.enemies) do
            local d=B.dist(s.hero.pos,e.pos)
            if enemy(s,e) and not e.attackImmune and d<1100 and s.hero.hpPct>0.48 and not s.hero.disarmed and not towerDanger(s,e.pos) then
                local allies,foes=counts(s,e.pos,1000)
                local c=s.core
                local protect=alive(c) and B.dist(c.pos,e.pos)<650 and (c.hpPct<0.65 or c.recentDamage>20)
                local participating=S.localFight(s,e)
                local setup=laneTradeSetup(s,e)
                local charge,why=S.localCharge(s,e)
                if charge then offer(out,'fight',0.8,charge,e,'local_fight:'..e.index)
                elseif participating then B.log('local_charge.block','Local Charge deferred: '..tostring(why),8) end
                local a,f=B.threat.balance(s,e.pos,1000)
                local landing=B.toward(e.pos,s.hero.pos,math.max(90,s.hero.range-20))
                if allies>=foes and a>=f*(protect and 0.8 or 0.95) and (participating or setup or creepsAt(s,landing)<3)
                    and (protect or participating or (s.hero.hpPct>0.65 and s.hero.recentDamage<45)) then
                    local i
                    if d<=s.hero.range+35 then i={kind='attack',target=e,reason=protect and 'Peel the attacker away from the core' or 'Start supported lane trade'}
                    else i=move(s,landing,protect and 'Approach to peel the core' or 'Close distance for a short trade') end
                    if i and setup and not protect and not participating then
                        i.tradeStart=true i.tradeIndex=e.index
                    end
                    offer(out,protect and 'protect_core' or participating and 'fight' or 'harass',protect and 0.86 or participating and 0.76 or setup and 0.58 or 0.5,i,e,'support_trade:'..e.index)
                end
            end
        end
    end
    function S.canGank(s,target)
        if s.hero.level<2 or s.hero.hpPct<0.72 or s.hero.recentDamage>35 or s.hero.rooted or s.hero.silenced
            or S.coreDanger(s) or not enemy(s,target) then return false end
        local charge=s.abilities.spirit_breaker_charge_of_darkness
        if not charge or not charge.castable or charge.level<1 or s.hero.mana<charge.manaCost+35 then return false end
        if s.now-lastGank<25 then return false end
        if B.map.classify(target.pos)==s.lane or B.dist(s.hero.pos,target.pos)>10000 then return false end
        if target.magicImmune or target.attackImmune or B.has(target,'modifier_item_sphere_target')
            or B.has(target,'modifier_item_lotus_orb_active') or not B.threat.safeEngage(s,target) then return false end
        local allyCount,setupCount=0,0
        for _,a in ipairs(B.near(s.allies,target.pos,1000)) do
            if alive(a) and a.hpPct>0.45 then
                setupCount=setupCount+1
                if a.attacking or a.recentDamage>10 or target.hpPct<0.8 or target.channeling then allyCount=allyCount+1 end
            end
        end
        -- Demonstration charges also start full-health ganks when a healthy ally
        -- is already in setup range and the local strength check is favourable.
        local friendly,hostile=B.threat.balance(s,target.pos,1100)
        if allyCount<1 and (setupCount<1 or friendly<hostile or target.hpPct<0.45) then return false end
        -- Charge bypasses GridNav. Check its straight corridor against known towers.
        local delta=B.sub(target.pos,s.hero.pos)
        local steps=math.max(1,math.ceil(B.dist(target.pos,s.hero.pos)/250))
        for n=1,steps do if towerDanger(s,B.add(s.hero.pos,B.scale(delta,n/steps)),120) then return false end end
        return true
    end
    local function ganks(out,s)
        if gank and s.now>gank.untilTime then gank=nil end
        for _,e in ipairs(s.enemies) do
            if S.canGank(s,e) then
                local bonus=gank and gank.index==e.index and 0.03 or 0
                offer(out,'gank',0.69+bonus+(1-e.hpPct)*0.05,{kind='cast',ability=s.abilities.spirit_breaker_charge_of_darkness,
                    castType='target',target=e,reason='Level 2+ rotation to a visible supported fight',gank=true},e,'gank:'..e.index)
            end
        end
    end
    local function wards(out,s)
        local item=s.items.item_ward_observer
        if not item or not item.castable or (item.charges or 0)<1 or S.coreDanger(s) or s.hero.hpPct<0.6 then return end
        for n,spot in ipairs(B.map.wardSpots(s)) do
            local p=spot.pos
            local dist=B.dist(s.hero.pos,p)
            if dist<1600 and (not wardAttempt[n] or s.now>wardAttempt[n]) then
                local covered=false
                for _,w in ipairs(s.wards) do if w.team==s.hero.team and w.name=='npc_dota_observer_wards' and B.dist(w.pos,p)<1300 then covered=true end end
                local threatened=false
                for _,e in ipairs(s.enemies) do if enemy(s,e) and B.dist(e.pos,p)<700 then threatened=true end end
                if not covered and not threatened and not towerDanger(s,p) then
                    local i
                    if dist<=item.range then i={kind='cast',ability=item,castType='position',pos=p,reason='Place lane vision from safe cast range',wardSpot=n}
                    else i=move(s,B.toward(p,s.hero.pos,math.max(100,item.range-60)),'Move into range to place lane vision') end
                    offer(out,'ward',0.46,i,nil,'support_ward:'..n)
                end
            end
        end
    end
    function S.candidates(s)
        local out={}
        if not s.hero.alive or s.hero.channeling or s.hero.casting or s.hero.stunned or B.charging(s) then return out end
        trades(out,s); ganks(out,s); wards(out,s)
        if s.time<600 then
            local i=patrolIntent(s)
            offer(out,'patrol',0.27,i,nil,'patrol')
            if not i and #out==0 and #B.near(s.enemies,s.hero.pos,1000)>0 then
                -- Escape/reposition must not require numerical superiority.
                offer(out,'reposition',0.33,move(s,B.threat.retreat(s),'Leave an unfavorable lane position'),nil,'reposition')
            end
        end
        return out
    end
    function S.issued(s,i)
        if i.tradeStart then
            local target=B.find(s.enemies,i.tradeIndex)
            if target and (not trade or trade.index~=i.tradeIndex) then
                trade={index=i.tradeIndex,expires=s.now+6,startHpPct=s.hero.hpPct,
                    targetHpPct=target.hpPct,hits=i.kind=='attack' and 1 or 0}
            elseif trade and i.kind=='attack' then trade.hits=trade.hits+1 end
        elseif i.tradeContinue and trade and trade.index==i.tradeIndex then
            trade.hits=trade.hits+1
        end
        if i.gank then lastGank=s.now; gank={index=i.target.index,untilTime=s.now+18} end
        if i.wardSpot then wardAttempt[i.wardSpot]=s.now+12 end
    end
end

end)()
initialize(B)
end

-- MODULE: src/modes.lua
do
local initialize = (function()
-- Snapshot-only support modes. Adapted rules (not engine orders) from OpenHyperAI:
-- FunLib/override_generic/mode_{laning,attack}_generic.lua: denies, partner
-- priority, creep aggro and helping allies; mode_rune_generic.lua: contest checks;
-- mode_ward_generic.lua + FunLib/aba_ward_utility.lua: typed wards and coverage;
-- FunLib/aba_site.lua: camp types and late-minute stacking; FunLib/aba_{push,
-- defend}.lua: local strength and creep cover; mode_assemble_generic.lua:
-- bounded grouping; mode_{roshan,side_shop,outpost}_generic.lua: team support.
-- Camp routing below is original: observed boxes/aggro replace upstream fixed
-- coordinates. No last-seen enemies, global objective timers or spawn guesses.
return function(B)
    local M = {}
    B.modes = M
    local active, campJob, lastClock, lastAct, heroIndex
    local blocked = {}
    local lastLaneHit = -math.huge
    local EMPTY = {}

    local function number(n)
        return type(n) == 'number' and n == n and math.abs(n) < math.huge
    end
    local function position(p)
        return type(p) == 'table' and number(p.x) and number(p.y)
            and (p.x ~= 0 or p.y ~= 0)
    end
    local function distance(a, b)
        if not position(a) or not position(b) then return math.huge end
        return B.dist(a, b)
    end
    local function alive(u)
        return u and u.alive == true and position(u.pos)
    end
    local function observed(u)
        return alive(u) and u.visible == true
    end
    local function hp(u)
        if number(u.hpPct) then return u.hpPct end
        if number(u.hp) and number(u.maxHp) and u.maxHp > 0 then return u.hp / u.maxHp end
        return 0
    end
    local function attackable(u)
        return observed(u) and not u.invulnerable and not u.attackImmune
    end
    local function enemy(s, u)
        return observed(u) and u.team ~= nil and u.team ~= s.hero.team
    end
    local function realAlly(s, u)
        return alive(u) and u.team == s.hero.team and not u.illusion
    end
    local function targeting(u, v)
        return v and v.index ~= nil and u.attackTarget == v.index
    end
    local function clock(s) return number(s.now) and s.now or s.time end
    local function gameTime(s) return number(s.time) and s.time or s.now end
    local function isLane(s) return gameTime(s) <= ((B.config or EMPTY).laningEnd or 600) end
    local function find(list, index)
        if index == nil then return nil end
        for _, u in pairs(list or EMPTY) do if u.index == index then return u end end
    end
    local function key(name, u, p)
        if u and u.index ~= nil then return name .. ':' .. tostring(u.index) end
        if position(p) then return name .. ':' .. math.floor(p.x) .. ':' .. math.floor(p.y) end
        return name
    end
    local function clearActive(s)
        if campJob and s then blocked[campJob.key] = clock(s) + 12 end
        active, campJob, lastAct = nil, nil, nil
    end
    function M.reset()
        active, campJob, lastClock, lastAct, heroIndex = nil, nil, nil, nil, nil
        blocked, lastLaneHit = {}, -math.huge
        if B.support then B.support.reset() end
    end
    local function sync(s)
        if not s or not s.hero or not number(clock(s)) or not number(gameTime(s)) then
            M.reset()
            return false
        end
        local now = clock(s)
        if (lastClock and now < lastClock) or (heroIndex and heroIndex ~= s.hero.index) then M.reset() end
        heroIndex, lastClock = s.hero.index, now
        for k, expiry in pairs(blocked) do if expiry <= now then blocked[k] = nil end end
        if not alive(s.hero) or s.hero.team == nil or s.hero.illusion then clearActive(s); return false end
        -- Hooks give immediate invalidation; this also expires state if a caller
        -- stops invoking act (OFF, another action, a pause or a channel).
        if lastAct and now - lastAct > 1.5 then clearActive(s) end
        if s.hero.channeling or s.hero.casting or s.hero.stunned then clearActive(s) end
        if campJob and now >= campJob.deadline then clearActive(s) end
        return true
    end
    local function strength(s, p, ratio)
        if not B.threat or not B.threat.balance then return false end
        local friendly, hostile = B.threat.balance(s, p, 1200)
        if number(friendly) and distance(s.hero.pos,p)>1200 then friendly=friendly+0.5+hp(s.hero)*0.5 end
        return number(friendly) and number(hostile) and friendly > 0 and friendly >= hostile * (ratio or 1.15)
    end
    local function towerDanger(s, p)
        for _, t in pairs(s.towers or EMPTY) do
            if enemy(s, t) and distance(p, t.pos) < (t.range or 700) + 170 then return true end
        end
        return false
    end
    local function safe(s, p, ratio, allowTower)
        if not position(p) or not strength(s, p, ratio) then return false end
        if not allowTower and towerDanger(s, p) then return false end
        -- Threat has no prescribed scale. Compare with the current location;
        -- strength and explicit tower/contest checks supply absolute guards.
        if B.threat.at then
            local there, here = B.threat.at(s, p), B.threat.at(s, s.hero.pos)
            local allowance=allowTower and 6 or 2.2
            if not number(there) or not number(here) or there>math.max(allowance,here+0.35) then return false end
        end
        return true
    end
    local function routeSafe(s, p, allowTower)
        return safe(s, p, 1.15, allowTower)
            and safe(s, B.toward(s.hero.pos, p, distance(s.hero.pos, p) * 0.5), 1.15, allowTower)
    end
    local function enemiesNear(s, p, r)
        local count = 0
        for _, e in pairs(s.enemies or EMPTY) do
            if enemy(s, e) and not e.illusion and distance(e.pos, p) <= r then count = count + 1 end
        end
        return count
    end
    local function quiet(s, p)
        return hp(s.hero) >= 0.5 and (s.hero.recentDamage or 0) <= 8
            and enemiesNear(s, s.hero.pos, 1000) == 0 and enemiesNear(s, p, 1100) == 0
            and routeSafe(s, p)
    end
    local function move(s, p, reason, allowTower)
        if not position(p) or not routeSafe(s, p, allowTower) then return nil end
        if distance(s.hero.pos, p) <= 85 then return {kind = 'hold', reason = reason} end
        if s.hero.rooted then return nil end
        return {kind = 'move', pos = p, reason = reason, allowTower = allowTower}
    end
    local function attack(s, u, reason, chase, allowTower)
        if not attackable(u) or s.hero.disarmed or not number(s.hero.range) then return nil end
        local d = distance(s.hero.pos, u.pos)
        if d > s.hero.range + 35 then
            if not chase or d > chase then return nil end
            return move(s, B.toward(u.pos, s.hero.pos, math.max(80, s.hero.range - 30)), reason, allowTower)
        end
        if not safe(s, s.hero.pos, 1.05, allowTower) then return nil end
        return {kind = 'attack', target = u, reason = reason, allowTower = allowTower}
    end
    local function offer(out, s, name, desire, intent, target, p, explicitKey)
        if not intent then return end
        local k = explicitKey or key(name, target, p)
        if blocked[k] then return end
        out[#out + 1] = {name = name, desire = desire, reason = intent.reason,
            target = target, pos = p or intent.pos, intent = intent, key = k}
    end
    local function core(s)
        if realAlly(s, s.core) then return s.core end
    end
    local function rear(s, anchor, spacing)
        if not position(anchor) then return nil end
        local away, nearest = nil, math.huge
        for _, e in pairs(s.enemies or EMPTY) do
            if enemy(s, e) and distance(anchor, e.pos) < nearest then away, nearest = e.pos, distance(anchor, e.pos) end
        end
        if away and nearest < 1800 and nearest > 1 then
            return B.add(anchor, B.scale(B.norm(B.sub(anchor, away)), spacing))
        end
        local t = B.map and B.map.friendlyTower and B.map.friendlyTower(s, s.lane)
        if alive(t) and distance(anchor, t.pos) > 150 then return B.toward(anchor, t.pos, spacing) end
        if distance(anchor, s.hero.pos) > 1 then return B.toward(anchor, s.hero.pos, spacing) end
        return anchor
    end

    -- Protection proposes an actual peel attack or an approach to attack range.
    -- Hero/item modules may replace it with a disable/save using the same target.
    local function combat(out, s)
        if B.support and isLane(s) then return end -- bounded lane trades live in support.lua
        local c = core(s)
        for _, e in pairs(s.enemies or EMPTY) do
            if enemy(s, e) and not e.illusion and attackable(e)
                and B.threat and B.threat.safeEngage and B.threat.safeEngage(s, e) then
                local protecting = c and distance(s.hero.pos, c.pos) < 1600
                    and (targeting(e, c) or (distance(e.pos, c.pos) < 500
                        and (c.recentDamage or 0) > 20))
                if protecting then
                    offer(out, s, 'protect_core', 0.84, attack(s, e, 'Peel the visible attacker off our core', 1300), e)
                end
                local engaged = targeting(e, s.hero)
                for _, a in pairs(s.allies or EMPTY) do
                    if realAlly(s, a) and distance(a.pos, e.pos) < 1000
                        and (targeting(a, e) or targeting(e, a) or
                            (a.attacking and distance(a.pos,e.pos)<(a.range or 150)+90 and (e.recentDamage or 0)>10)) then engaged = true end
                end
                if engaged and hp(s.hero) >= 0.4 then
                    offer(out, s, 'fight', 0.65, attack(s, e, 'Assist the nearby fight', 1100), e)
                elseif hp(s.hero) >= 0.6 and (s.hero.recentDamage or 0) <= 8 then
                    local aggro = 0
                    for _, creep in pairs(s.creeps or EMPTY) do
                        if enemy(s, creep) and distance(creep.pos, s.hero.pos) < 600 then aggro = aggro + 1 end
                    end
                    if aggro <= 1 then
                        offer(out, s, 'harass', 0.39, attack(s, e, 'Take a short low-aggro trade', (s.hero.range or 0) + 100), e)
                    end
                end
            end
        end
    end
    local function hitDelay(u, target)
        if not number(u.attackPoint) or not number(u.range) then return nil end
        local delay = u.attackPoint
        if u.range > 250 then
            if not number(u.projectileSpeed) or u.projectileSpeed <= 0 then return nil end
            delay = delay + distance(u.pos, target.pos) / u.projectileSpeed
        end
        return delay
    end
    local function canLastHit(s, u)
        local h = s.hero
        if not number(u.hp) or not number(u.armorFactor) or not number(h.damage) then return false end
        local delay = hitDelay(h, u)
        if not delay or distance(h.pos, u.pos) > (h.range or 0) + 20 then return false end
        local loss = math.max(0, u.healthLossRate or 0)
        -- Avoid speculative future last hits: already killable and still alive
        -- at impact under the observed health trend, with a damage margin.
        return u.hp <= h.damage * u.armorFactor * 0.9 and u.hp - loss * delay > 1
    end
    local function coreCanTake(s, u)
        local candidates = {}
        if core(s) then candidates[#candidates + 1] = s.core end
        for _, a in pairs(s.allies or EMPTY) do
            if realAlly(s, a) and (a.role == nil or a.role <= 3) then candidates[#candidates + 1] = a end
        end
        for _, a in ipairs(candidates) do
            if targeting(a, u) then return true end -- includes an attack already in flight
            if distance(a.pos, u.pos) < 1100 and not a.stunned and not a.disarmed then
                if not number(a.range) or not number(a.moveSpeed) or a.moveSpeed <= 0 then return true end
                local delay = hitDelay(a, u)
                if not delay then return true end
                local travel = math.max(0, distance(a.pos, u.pos) - a.range) / a.moveSpeed
                if a.rooted and travel > 0 then travel = math.huge end
                local loss = u.healthLossRate or 0
                if loss <= 0 or (u.hp or math.huge) / loss > travel + delay then return true end
            end
        end
        return false
    end
    M.coreCanTake=coreCanTake
    local function lane(out, s)
        if not isLane(s) then return end
        for _, u in pairs(s.creeps or EMPTY) do
            if attackable(u) and canLastHit(s, u) then
                if u.team == s.hero.team and hp(u) < 0.49 then
                    offer(out, s, 'deny', 0.52, attack(s, u, 'Deny a killable allied creep'), u)
                elseif enemy(s, u) and clock(s) - lastLaneHit >= 8 and not coreCanTake(s, u)
                    and enemiesNear(s, s.hero.pos, 800) == 0 then
                    offer(out, s, 'last_hit', 0.35, attack(s, u, 'Salvage a safe last hit unavailable to a core'), u)
                end
            end
        end
        local c = core(s)
        if c and B.map.coreOnLane and not B.map.coreOnLane(s,c) then c=nil end
        local anchor = c and c.pos or (B.map and B.map.lanePoint and B.map.lanePoint(s, s.lane))
        local p = c and rear(s,anchor,s.role==5 and 280 or 220) or anchor
        offer(out, s, 'lane', 0.24, move(s, p, 'Position behind the lane partner or lane front'), c, p, 'lane')
    end
    local function runes(out, s)
        for _, r in pairs(s.runes or EMPTY) do
            local d = distance(s.hero.pos, r.pos)
            if r.handle and r.index ~= nil and type(r.type)=='number' and r.type>=0 and d < 1800 and quiet(s, r.pos) then
                local claimed = false
                for _, a in pairs(s.allies or EMPTY) do
                    if realAlly(s, a) and distance(a.pos, r.pos) + 150 < d then claimed = true end
                end
                if not claimed then
                    local intent = d <= 180 and {kind = 'rune', target = r, reason = 'Collect an observed uncontested rune'}
                        or move(s, r.pos, 'Approach the observed rune')
                    offer(out, s, 'rune', 0.43 - d / 18000, intent, r)
                end
            end
        end
    end
    local function wardKind(w)
        if w.name == 'npc_dota_observer_wards' then return 'observer' end
        if w.name == 'npc_dota_sentry_wards' then return 'sentry' end
    end
    local function coverage(s, p, kind, radius)
        for _, w in pairs(s.wards or EMPTY) do
            if alive(w) and w.team == s.hero.team and wardKind(w) == kind and distance(p, w.pos) < radius then return true end
        end
        return false
    end
    local function wardItem(s, kind)
        local items = s.items or EMPTY
        local direct = items['item_ward_' .. kind]
        if direct and direct.castable and (direct.charges or 0) > 0 then return direct end
        local both = items.item_ward_dispenser
        -- Neither selected mode nor charge mapping is verified in this adapter.
        if both and B.log then B.log('modes.dispenser', 'Ward dispenser disabled: selection and charge mapping are unverified', 60) end
        return nil
    end
    local function plant(out, s, p, kind, desire)
        local item = wardItem(s, kind)
        if not item or not number(item.range) or distance(s.hero.pos, p) > 2200 or not quiet(s, p)
            or coverage(s, p, kind, kind == 'observer' and 1300 or 850) then return end
        local intent
        if distance(s.hero.pos, p) <= item.range then
            intent = {kind = 'cast', ability = item, castType = 'position', pos = p,
                wardType = kind, itemName = item.name, reason = 'Place ' .. kind .. ' vision'}
        else
            -- Ward cliffs need not be walkable. Approach from this side only.
            intent = move(s, B.toward(p, s.hero.pos, math.max(100, item.range - 60)), 'Approach ' .. kind .. ' cast range')
        end
        offer(out, s, kind == 'sentry' and 'deward' or 'ward', desire, intent, nil, p, key('ward_' .. kind, nil, p))
    end
    local function wards(out, s)
        for _, w in pairs(s.wards or EMPTY) do
            if enemy(s, w) and wardKind(w) and quiet(s, w.pos) then
                offer(out, s, 'deward', 0.49, attack(s, w, 'Destroy a revealed enemy ward', 950), w)
                -- Only observed enemy wards justify a sentry, never hidden handles.
                if distance(s.hero.pos, w.pos) > (s.hero.range or 0) + 35 then plant(out, s, w.pos, 'sentry', 0.42) end
            end
        end
        if B.map and B.map.wardSpots then
            for _, spot in pairs(B.map.wardSpots(s) or EMPTY) do
                local p = spot.pos or spot
                local kind = spot.wardType or 'observer'
                if kind == 'observer' or kind == 'sentry' then plant(out, s, p, kind, 0.34) end
            end
        end
    end

    local function inBox(p, box, margin)
        margin = margin or 0
        return position(p) and box and position(box.min) and position(box.max)
            and p.x >= box.min.x - margin and p.x <= box.max.x + margin
            and p.y >= box.min.y - margin and p.y <= box.max.y + margin
    end
    local function validCamp(c)
        return c and c.index ~= nil and position(c.pos) and c.box
            and position(c.box.min) and position(c.box.max)
            and c.box.max.x > c.box.min.x and c.box.max.y > c.box.min.y
            and inBox(c.pos, c.box) and (c.type == 'small' or c.type == 'medium' or c.type == 'large')
    end
    local function campExit(s, c, toward)
        if not position(toward) or distance(c.pos, toward) < 1 then return nil end
        local dir = B.norm(B.sub(toward, c.pos))
        local tx, ty = math.huge, math.huge
        if math.abs(dir.x) > 0.001 then tx = ((dir.x > 0 and c.box.max.x or c.box.min.x) - c.pos.x) / dir.x end
        if math.abs(dir.y) > 0.001 then ty = ((dir.y > 0 and c.box.max.y or c.box.min.y) - c.pos.y) / dir.y end
        local p = B.add(c.pos, B.scale(dir, math.min(tx, ty) + 450))
        if not inBox(p, c.box, 150) and routeSafe(s, p) then return p end
    end
    local function campUnits(s, c)
        local list = {}
        for _, u in pairs(s.neutrals or EMPTY) do
            if attackable(u) and inBox(u.pos, c.box, 30) then list[#list + 1] = u end
        end
        return list
    end
    local function pullWave(s, c)
        local best, d = nil, 1000
        for _, u in pairs(s.creeps or EMPTY) do
            if alive(u) and u.team == s.hero.team and not u.attacking and not inBox(u.pos, c.box, 150)
                and distance(u.pos, c.pos) < d then best, d = u, distance(u.pos, c.pos) end
        end
        return best
    end
    local function campProposal(s, advance)
        local job = campJob
        if not job then return nil end
        local c = find(s.camps, job.camp)
        local u = find(s.neutrals, job.neutral)
        if not validCamp(c) or not observed(u) or hp(s.hero) < 0.6
            or enemiesNear(s, c.pos, 1100) > 0 or enemiesNear(s, s.hero.pos, 1000) > 0
            or not routeSafe(s, job.exit) then return nil end
        local now = clock(s)
        local phase = job.phase
        local aggro = targeting(u, s.hero) or (u.velocity and
            distance(u.pos,s.hero.pos)<850 and (u.velocity.x*(s.hero.pos.x-u.pos.x)+u.velocity.y*(s.hero.pos.y-u.pos.y))>20000)
        if phase == 'approach' and distance(s.hero.pos, u.pos) <= (s.hero.range or 0) + 35 then
            phase = 'aggro'
            if advance then job.phase, job.phaseAt = phase, now end
        end
        if phase == 'approach' then
            return move(s, B.toward(u.pos, s.hero.pos, math.max(80, (s.hero.range or 150) - 25)), 'Approach the observed camp')
        end
        if phase == 'aggro' then
            if aggro then
                phase = 'drag'
                if advance then job.phase, job.phaseAt = phase, now end
            else
                if now - job.phaseAt > 2.5 or gameTime(s) > job.latestAggro then
                    if B.log then B.log('modes.camp_aggro', 'Camp attempt expired without observed neutral aggro', 30) end
                    return nil
                end
                return attack(s, u, 'Draw neutral aggro before dragging', 750)
            end
        end
        if phase == 'drag' or phase == 'clear' then
            if job.name == 'pull' then
                local wave = find(s.creeps, job.wave)
                if not alive(wave) then return nil end
                if targeting(u, wave) or targeting(wave, u) then return nil end -- observed handoff completes the pull
            end
            -- No presumed success from an issued attack. Losing observed aggro
            -- aborts the job; do not run to an old exit or re-aggro indefinitely.
            if not aggro then return nil end
            local allOutside = not inBox(s.hero.pos, c.box, 80)
            for _, id in ipairs(job.members) do
                local n = find(s.neutrals, id)
                if not observed(n) or inBox(n.pos, c.box, 80) then allOutside = false end
            end
            if job.name == 'stack' and gameTime(s) >= job.spawnAt + 0.5 then return nil end
            if job.name == 'stack' and allOutside then
                if advance then job.phase = 'clear' end
                return move(s, job.exit, 'Keep the hero and observed neutrals outside the spawn box')
            end
            return move(s, job.exit, 'Lead aggroed neutrals outside the camp box')
        end
    end
    local function camps(out, s)
        if campJob then
            offer(out, s, campJob.name, 0.47, campProposal(s, false), nil, campJob.exit, campJob.key)
            return
        end
        if not number(s.hero.moveSpeed) or s.hero.moveSpeed <= 0 or not number(s.hero.range)
            or not number(s.hero.attackPoint) or s.hero.disarmed or hp(s.hero) < 0.65 then return end
        local t = gameTime(s)
        if t < 60 then return end
        local sec = t % 60
        for _, c in pairs(s.camps or EMPTY) do
            if validCamp(c) and distance(s.hero.pos, c.pos) < 1000 and quiet(s, c.pos) then
                local units = campUnits(s, c)
                local u = units[1]
                local free = u and u.index ~= nil
                for _, n in ipairs(units) do if n.attackTarget ~= nil then free = false end end
                if free then
                    local name, exit, wave, latest, spawnAt
                    if sec >= 48 and sec <= 55 then
                        exit = campExit(s, c, s.hero.pos)
                        local travel = exit and distance(c.pos, exit) / math.max(1, u.moveSpeed or 0)
                        if number(u.moveSpeed) and travel and travel < 8 then
                            local tagAt = math.floor(t / 60) * 60 + 60 - travel - 1.5
                            local approach = math.max(0, distance(s.hero.pos, u.pos) - s.hero.range) / s.hero.moveSpeed
                            local delay = hitDelay(s.hero, u)
                            if delay and t + approach + delay >= tagAt - 1 and t + approach + delay <= tagAt + 0.7 then
                                name, latest, spawnAt = 'stack', tagAt + 1, math.floor(t / 60) * 60 + 60
                            end
                        end
                    elseif isLane(s) and c.type == 'small' and ((sec >= 12 and sec <= 19) or (sec >= 42 and sec <= 47)) then
                        wave = pullWave(s, c)
                        local partner = core(s)
                        local tower = B.map and B.map.friendlyTower and B.map.friendlyTower(s, s.lane)
                        -- Pull only an advanced lane, with a healthy unpressured
                        -- partner nearby; real wave position decides the route.
                        if wave and partner and hp(partner) > 0.65 and distance(partner.pos, c.pos) < 1800
                            and (partner.recentDamage or 0) <= 8 and enemiesNear(s, partner.pos, 1000) == 0
                            and alive(tower) and distance(partner.pos, tower.pos) > 1300 then
                            exit = campExit(s, c, wave.pos)
                            if exit and distance(exit, wave.pos) < 550 then name, latest = 'pull', t + 3 end
                        end
                    end
                    if name and exit then
                        local k = key(name, c)
                        local intent = attack(s, u, 'Approach and tag the camp for a ' .. name, 1000)
                        offer(out, s, name, 0.41, intent, u, exit, k)
                        local candidate = out[#out]
                        if candidate and candidate.key == k then
                            local members = {}
                            for _, n in ipairs(units) do if n.index ~= nil then members[#members + 1] = n.index end end
                            candidate._camp = {name = name, key = k, camp = c.index, neutral = u.index,
                                wave = wave and wave.index, exit = exit, members = members, phase = 'approach',
                                phaseAt = clock(s), deadline = clock(s) + 13, latestAggro = latest, spawnAt = spawnAt}
                        end
                    end
                end
            end
        end
    end

    function M.groupTarget(s)
        local t = gameTime(s)
        local best, bestScore
        for _, a in pairs(s.allies or EMPTY) do
            if realAlly(s, a) and hp(a) > 0.45 then
                local nearby = 0
                for _, other in pairs(s.allies or EMPTY) do
                    if realAlly(s, other) and other.index ~= a.index
                        and distance(other.pos, a.pos) < 1000 then nearby = nearby + 1 end
                end
                local roleBias = 0
                if t >= 600 and t < 1800 then
                    -- During the farming window, pos 1 is deliberately the last
                    -- grouping anchor. Prefer another support, then pos 2/3.
                    if a.role == 4 or a.role == 5 then roleBias = -900
                    elseif a.role == 2 or a.role == 3 then roleBias = -600
                    elseif a.role == 1 then roleBias = 1800
                    else roleBias = -250 end
                end
                local score = roleBias + distance(s.hero.pos, a.pos) * 0.12 - nearby * 500
                if bestScore == nil or score < bestScore then best, bestScore = a, score end
            end
        end
        return best
    end
    local function grouping(out, s)
        if isLane(s) then return end
        local a = M.groupTarget(s)
        if not a then return end
        local p = rear(s, a.pos, 320)
        local activity=0
        for _,ally in pairs(s.allies or EMPTY) do
            if realAlly(s,ally) and distance(ally.pos,a.pos)<1100
                and (ally.attacking or ally.casting or ally.channeling or (ally.recentDamage or 0)>8) then
                activity=activity+1
            end
        end
        -- Idle proximity to teammates is not a task. Farm has priority until
        -- the preferred anchor is actually grouping for an observed action.
        local desire=activity>0 and (distance(s.hero.pos,p)>600 and 0.30 or 0.16) or 0.10
        offer(out, s, 'group', desire, move(s, p,
            'Stay in support range of the preferred allied group anchor'), a, p)
    end
    local function buildings(out, s)
        for _, t in pairs(s.towers or EMPTY) do
            if observed(t) and distance(s.hero.pos, t.pos) < 2200 then
                if t.team == s.hero.team then
                    for _, u in pairs(s.enemies or EMPTY) do
                        if enemy(s, u) and not u.illusion and distance(u.pos, t.pos) < 950
                            and B.threat.safeEngage(s, u) then
                            offer(out, s, 'defend', 0.70, attack(s, u, 'Help defend the allied tower', 1300), u)
                        end
                    end
                    for _, u in pairs(s.creeps or EMPTY) do
                        if enemy(s, u) and distance(u.pos, t.pos) < 800
                            and (not isLane(s) or (canLastHit(s,u) and not coreCanTake(s,u))) then
                            offer(out, s, 'defend', 0.48, attack(s, u, 'Clear the wave threatening the allied tower', 1000), u)
                        end
                    end
                elseif enemy(s, t) and attackable(t) and not isLane(s) and hp(s.hero) > 0.6 then
                    local cover, allies = 0, 0
                    for _, u in pairs(s.creeps or EMPTY) do
                        if alive(u) and u.team == s.hero.team and hp(u) > 0.35
                            and distance(u.pos, t.pos) < (t.range or 700) then cover = cover + 1 end
                    end
                    for _, a in pairs(s.allies or EMPTY) do
                        if realAlly(s, a) and hp(a) > 0.5 and distance(a.pos, t.pos) < 1000 then allies = allies + 1 end
                    end
                    local tank = find(s.creeps, t.attackTarget)
                    if cover >= 3 and allies >= 1 and alive(tank) and tank.team == s.hero.team and hp(tank) > 0.4
                        and strength(s, t.pos, 1.4) and enemiesNear(s, t.pos, 1400) == 0 then
                        offer(out, s, 'push', 0.38, attack(s, t, 'Hit the tower behind allied creep cover', 1300, true), t)
                    end
                end
            end
        end
    end
    local function objectives(out, s)
        local seen = {}
        for _, list in ipairs({s.objectives or EMPTY, s.neutrals or EMPTY, s.structures or EMPTY}) do
            for _, u in pairs(list) do
                if observed(u) and u.index ~= nil and not seen[u.index] then
                    seen[u.index] = true
                    local name = string.lower(u.name or '')
                    local boss = name == 'npc_dota_roshan' and 'roshan'
                        or ((name:find('tormentor', 1, true) or name == 'npc_dota_miniboss') and 'tormentor')
                    if boss and attackable(u) and distance(s.hero.pos, u.pos) < 1600
                        and hp(s.hero) >= (boss == 'tormentor' and 0.7 or 0.6) and quiet(s, u.pos) then
                        local count, cores, attacking, dps = 0, 0, 0, 0
                        for _, a in pairs(s.allies or EMPTY) do
                            if realAlly(s, a) and hp(a) >= 0.6 and distance(a.pos, u.pos) < 900 then
                                count = count + 1
                                if a.role and a.role <= 3 then cores = cores + 1 end
                                if a.attacking and (targeting(a,u) or (distance(a.pos,u.pos)<(a.range or 150)+120
                                    and (u.recentDamage or 0)>20)) then attacking = attacking + 1 end
                                if number(a.damage) and number(a.attackPeriod) and a.attackPeriod > 0 then dps = dps + a.damage / a.attackPeriod end
                            end
                        end
                        if count >= (boss == 'tormentor' and 3 or 2) and cores >= 1 and attacking >= 2
                            and dps >= (boss == 'tormentor' and 250 or 160) then
                            offer(out, s, boss, 0.53, attack(s, u, 'Assist the healthy team already attacking ' .. boss, 1400), u)
                        end
                    elseif name:find('outpost', 1, true) and B.log then
                        B.log('modes.outpost', 'Outpost interaction disabled: capture API is undocumented', 60)
                    end
                end
            end
        end
    end
    local function farm(out, s)
        if gameTime(s) <= 600 or hp(s.hero) < 0.6 then return end
        local offered=false
        for _, u in pairs(s.creeps or EMPTY) do
            if enemy(s, u) and attackable(u) and distance(s.hero.pos, u.pos) < 2400 and quiet(s, u.pos) then
                local reserved = false
                for _, a in pairs(s.allies or EMPTY) do
                    if realAlly(s, a) and (a.role == nil or a.role <= 3) and distance(a.pos, u.pos) < 1500 then reserved = true end
                end
                if not reserved then
                    offer(out, s, 'farm', 0.34, attack(s, u,'Push spare lane farm away from allied cores',2400),u)
                    offered=true
                end
            end
        end
        for _,u in pairs(s.neutrals or EMPTY) do
            if attackable(u) and distance(s.hero.pos,u.pos)<1800 and quiet(s,u.pos)
                and not u.name:find('ancient') and not u.name:find('roshan') and not u.name:find('miniboss') then
                local reserved=false
                for _,a in ipairs(s.allies or EMPTY) do
                    if realAlly(s,a) and (a.role==nil or a.role<=3) and distance(a.pos,u.pos)<1500 then reserved=true end
                end
                if not reserved then
                    offer(out,s,'farm',0.31,attack(s,u,'Farm a nearby unreserved neutral camp',1800),u)
                    offered=true
                end
            end
        end
        local best,bestDistance
        for _,laneName in ipairs({'top','mid','bot'}) do
            local p=B.map.lanePoint(s,laneName)
            local d=distance(s.hero.pos,p)
            if not bestDistance or d<bestDistance then best,bestDistance=p,d end
        end
        if best then
            offer(out,s,'farm',offered and 0.20 or 0.26,
                move(s,best,'Move to the nearest lane for spare farm while the map is quiet'),nil,best,'late_lane')
        end
    end
    function M.candidates(s)
        local out = {}
        if not sync(s) then return out end
        if s.hero.channeling or s.hero.casting or s.hero.stunned then return out end
        if B.threat and B.threat.safety then
            local emergency = B.threat.safety(s)
            if emergency then clearActive(s); return {emergency} end
        end
        combat(out, s)
        lane(out, s)
        runes(out, s)
        wards(out, s)
        camps(out, s)
        grouping(out, s)
        buildings(out, s)
        objectives(out, s)
        farm(out, s)
        if B.support then for _,m in ipairs(B.support.candidates(s)) do out[#out+1]=m end end
        if #out == 0 then offer(out, s, 'idle', 0.01, {kind = 'hold', reason = 'No safe observed task'}, nil, nil, 'idle') end
        return out
    end
    -- Optional scheduler hooks: call onExit(s, oldMode) whenever any other
    -- subsystem preempts modes (including OFF/emergency), even within 1.5s.
    -- onEnter(s, newMode) is optional; act detects ordinary mode/key switches.
    function M.onExit(s, mode)
        clearActive(s)
    end
    function M.onEnter(s, mode)
        if not mode or not active or active.key ~= (mode.key or mode.name) then clearActive(s) end
    end
    function M.act(s, mode)
        if not sync(s) or not mode or type(mode.name) ~= 'string' then clearActive(s); return nil end
        local k = mode.key or mode.name
        if active and active.key ~= k then clearActive(s) end
        local selected
        -- Rebuild, never execute mode.intent from an earlier snapshot. Expired
        -- entities, changed ownership, lost cover and consumed runes disappear.
        for _, current in ipairs(M.candidates(s)) do
            if current.name == mode.name and (not mode.key or current.key == mode.key) then selected = current; break end
        end
        if not selected then clearActive(s); return nil end
        local now = clock(s)
        if not active then active = {key = k, since = now} end
        local limited = selected.name == 'ward' or selected.name == 'deward' or selected.name == 'rune' or selected.name == 'outpost'
        if limited and now - active.since > 14 then blocked[selected.key or k] = now + 10; clearActive(s); return nil end
        lastAct = now
        if selected._camp and not campJob then campJob = selected._camp end
        local intent = selected.intent
        if campJob then
            intent = campProposal(s, true)
            if not intent then clearActive(s); return nil end
        end
        if selected.name == 'last_hit' and intent and intent.kind == 'attack' then lastLaneHit = now end
        return intent
    end
end

end)()
initialize(B)
end

-- MODULE: src/executor.lua
do
local initialize = (function()
return function(B)
    local E={lastAt=-100,lockUntil=0,count=0} B.executor=E
    local function invoke(lib,method,...)
        if not B.libs[lib] or type(B.libs[lib][method])~='function' then
            B.log('executor.'..method,'Unavailable order: '..lib..'.'..method,30) return false
        end
        local ok,err=pcall(B.libs[lib][method],...)
        if not ok then B.log('executor.error',tostring(err),3) end
        return ok -- Umbrella orders return nil even when accepted.
    end
    local function valid(u)
        return u and u.handle and B.call('Entity','IsEntity',false,u.handle)
    end
    local function order(s,kind,target,pos,ability)
        local code=B.enum('UnitOrder',kind)
        local issuer=B.enum('PlayerOrderIssuer','DOTA_ORDER_ISSUER_PASSED_UNIT_ONLY')
        if not code or not issuer then B.log('order_enum','Order enum unavailable: '..kind,30) return false end
        return invoke('Player','PrepareUnitOrders',s.player,code,target,pos and B.vec(pos) or B.vec(s.hero.pos),
            ability,issuer,s.hero.handle,false,false,false,false,'spirit_breaker_bot',true)
    end
    function E.reset() E.lastAt=-100 E.lockUntil=0 E.pending=nil E.lastKey=nil E.lastPos=nil E.lastIntent=nil E.quickbuyJob=nil B.chargeTarget=nil end
    function E.queueTick(s)
        local job=E.quickbuyJob
        if not job or s.now<job.nextAt then return end
        local name=job.names[job.index]
        if not invoke('Engine','SetQuickBuy',name:gsub('^item_',''),job.index==1 and job.reset or false) then
            E.quickbuyJob=nil B.items.reset() return false
        end
        B.log('quickbuy.'..job.index,'Quick-buy add '..name..' reset='..tostring(job.index==1 and job.reset or false),0)
        job.index=job.index+1 job.nextAt=s.now+0.25
        if job.index>#job.names then E.quickbuyJob=nil end
        return true
    end
    function E.poll(s)
        E.queueTick(s)
        local p=E.pending if not p then return end
        local a=p.name and ((p.item and s.items or s.abilities)[p.name])
        local done=false
        if p.kind=='cast' then
            done=(a and (a.cooldown>p.cooldown+0.05 or (a.charges and a.charges<p.charges))) or false
            if p.name=='spirit_breaker_charge_of_darkness' then done=B.charging(s) end
            if p.item and not a and not s.ownedItems[p.name] then done=true end
        elseif p.kind=='level' then done=a and a.level>p.level
        elseif p.kind=='rune' then done=B.find(s.runes,p.target)==nil end
        if done or s.now>p.expires then
            E.pending=nil
            E.lastResult={ok=done,reason=done and 'Observed action effect' or 'No confirmation before timeout',time=s.now}
            if p.sequence and B.api then B.api.finish(p.sequence,done,E.lastResult.reason) end
        end
    end
    function E.execute(s,intent)
        if not intent or not B.enabled or not s or not s.hero.alive or s.hero.illusion then return false end
        if s.hero.name~='npc_dota_hero_spirit_breaker' then return false end
        local kind=intent.kind
        if kind=='quickbuy' then
            if E.quickbuyJob then return false end
            local names=intent.itemNames or {intent.itemName}
            if #names==0 or #names>16 then return false end
            for _,name in ipairs(names) do if type(name)~='string' or not name:match('^[%w_]+$') then return false end end
            E.quickbuyJob={names=names,index=1,nextAt=s.now,reset=intent.reset~=false}
            return E.queueTick(s)~=false
        end
        local charging=B.charging(s)
        local chargeBulldoze=charging and kind=='cast' and intent.ability
            and intent.ability.name=='spirit_breaker_bulldoze' and intent.castType=='none'
        local locked=charging or s.hero.channeling or s.hero.casting or B.has(s.hero,'modifier_teleporting')
        if locked and not chargeBulldoze and not (intent.emergency and kind=='move') then return false end
        if s.now<E.lockUntil and not intent.emergency then return false end
        if E.pending and (kind=='cast' or kind=='rune' or kind=='level') then return false end
        if s.now-E.lastAt<(intent.emergency and 0.12 or 0.18) then return false end
        if s.hero.stunned then return false end
        if (kind=='move' or kind=='rune') and s.hero.rooted then return false end
        local target=intent.target
        if target then
            if not valid(target) then return false end
            if target.team~=nil and target.team~=s.hero.team then
                if B.call('Entity','IsDormant',true,target.handle) or not B.call('NPC','IsVisible',false,target.handle) then return false end
                if not B.call('Entity','IsAlive',false,target.handle) then return false end
            end
        end
        local key=kind..':'..tostring(target and target.index or '')..':'
            ..tostring(intent.ability and intent.ability.name or intent.item and intent.item.name or '')
        if kind=='move' then
            local p=B.navigation.next(s,intent.pos,intent.allowTower,intent.emergency)
            if not p then return false end
            if E.lastKey==key and B.dist(p,E.lastPos)<55 and s.now-E.lastAt<0.55 then return false end
            if order(s,'DOTA_UNIT_ORDER_MOVE_TO_POSITION',nil,p,nil) then
                E.lastAt=s.now E.lastKey=key E.lastPos=p E.count=E.count+1 E.lastIntent=intent return true
            end
            return false
        end
        if kind=='drop' then
            local item=intent.item
            if not item or not item.handle or type(item.slot)~='number' or item.slot<0 or item.slot>8 then return false end
            if (item.name or ''):find('boots',1,true) then return false end
            if not B.call('Item','IsDroppable',false,item.handle) then return false end
            local p=intent.pos or B.toward(s.hero.pos,B.map.home(s),80)
            if not order(s,'DOTA_UNIT_ORDER_DROP_ITEM',nil,p,item.handle) then return false end
            E.lockUntil=s.now+0.2
        elseif kind=='move_item' then
            local item,slot=intent.item,intent.destinationSlot
            if not item or not item.handle or type(item.slot)~='number' or item.slot<6 or item.slot>8
                or type(slot)~='number' or slot<0 or slot>5 then return false end
            for _,current in ipairs(s.inventory or {}) do
                if current.slot==slot and not intent.swap then return false end
            end
            -- MOVE_ITEM encodes the destination inventory slot in target_index.
            if not order(s,'DOTA_UNIT_ORDER_MOVE_ITEM',slot,nil,item.handle) then return false end
            E.lockUntil=s.now+0.2
        elseif kind=='hold' then
            if E.lastKey==key and s.now-E.lastAt<0.7 then return false end
            if not invoke('Player','HoldPosition',s.player,s.hero.handle,false,false,false,'spirit_breaker_bot') then return false end
        elseif kind=='attack' then
            if not target or not target.alive or target.invulnerable or target.attackImmune or s.hero.disarmed then return false end
            if target.team==s.hero.team then
                if not B.find(s.creeps,target.index) or target.hpPct>=0.5 then return false end
            elseif s.time<600 and B.find(s.creeps,target.index) then
                if B.modes.coreCanTake and B.modes.coreCanTake(s,target) then return false end
            end
            if B.dist(s.hero.pos,target.pos)>s.hero.range+55 then return false end
            if not intent.allowTower then
                for _,t in ipairs(s.towers) do
                    if t.team~=s.hero.team and B.dist(t.pos,s.hero.pos)<t.range+80 then return false end
                end
            end
            -- Never hand an unbounded chase to the engine. Range is checked again each refresh.
            if E.lastKey==key and s.now-E.lastAt<math.max(0.45,s.hero.attackPeriod*0.8) then return false end
            if not invoke('Player','AttackTarget',s.player,s.hero.handle,target.handle,false,false,false,'spirit_breaker_bot',true) then return false end
            E.lockUntil=s.now+s.hero.attackPoint+0.12
        elseif kind=='cast' then
            local a=intent.ability
            if not a or not a.handle or a.hidden or a.passive then return false end
            if a.item and s.hero.muted or not a.item and s.hero.silenced then return false end
            if not B.call('Ability','IsCastable',false,a.handle,s.hero.mana) then return false end
            if E.pending then return false end
            if a.name=='item_ward_dispenser' then B.log('dispenser','Ward dispenser selection unverified; refusing cast',30) return false end
            local bit=(intent.castType=='target' or intent.castType=='tree') and 8
                or (intent.castType=='position' and 16 or 4)
            if not B.flag(a.behavior,bit) then return false end
            if intent.castType=='target' or intent.castType=='tree' then
                if not target or target.invulnerable then return false end
                if intent.castType~='tree' and not B.flag(a.targetTeam,target.team==s.hero.team and 1 or 2) then return false end
                if target.index~=s.hero.index and not B.inCastRange(a,B.dist(s.hero.pos,target.pos),25) then
                    B.log('cast.range','Cast rejected by range: '..a.name..' range='..tostring(a.range),8)
                    return false
                end
                if a.name=='spirit_breaker_charge_of_darkness'
                    and (s.hero.rooted or (not intent.forceCharge and not B.threat.safeEngage(s,target))) then return false end
                if not invoke('Ability','CastTarget',a.handle,target.handle,false,false,false,'spirit_breaker_bot') then return false end
                if a.name=='spirit_breaker_charge_of_darkness' then
                    B.chargeTarget={index=target.index,issuedAt=s.now}
                end
            elseif intent.castType=='position' then
                if not intent.pos then return false end
                if a.name~='item_tpscroll' and (a.range<=0 or B.dist(s.hero.pos,intent.pos)>a.range+25) then return false end
                if not invoke('Ability','CastPosition',a.handle,B.vec(intent.pos),false,false,false,'spirit_breaker_bot',true) then return false end
            else
                if not invoke('Ability','CastNoTarget',a.handle,false,false,false,'spirit_breaker_bot') then return false end
            end
            E.lockUntil=s.now+math.max(0.25,a.castPoint+0.2)
            E.pending={kind=kind,name=a.name,item=a.item,cooldown=a.cooldown,charges=a.charges or 0,
                expires=s.now+math.max(2,a.castPoint+1),sequence=intent.sequence}
        elseif kind=='level' then
            local a=intent.ability
            if not a or not B.call('Ability','CanBeUpgraded',false,a.handle) then return false end
            if not order(s,'DOTA_UNIT_ORDER_TRAIN_ABILITY',nil,nil,a.handle) then return false end
            E.pending={kind=kind,name=a.name,level=a.level,expires=s.now+2,sequence=intent.sequence}
        elseif kind=='rune' then
            if not target or B.dist(s.hero.pos,target.pos)>200 then return false end
            if not order(s,'DOTA_UNIT_ORDER_PICKUP_RUNE',target.handle,target.pos,nil) then return false end
            E.pending={kind=kind,target=target.index,expires=s.now+2,sequence=intent.sequence}
        elseif kind=='interact' then
            B.log('unsupported_interaction','Outpost capture disabled: no verified safe interaction',30) return false
        else return false end
        E.lastAt=s.now E.lastKey=key E.lastPos=nil E.count=E.count+1 E.lastIntent=intent
        if B.support then B.support.issued(s,intent) end
        return true
    end
    function E.stop(s)
        if s and s.hero and s.hero.name=='npc_dota_hero_spirit_breaker' then
            invoke('Player','HoldPosition',s.player,s.hero.handle,false,false,false,'spirit_breaker_bot_off')
        end
        E.reset()
    end
end

end)()
initialize(B)
end

-- MODULE: src/arbiter.lua
do
local initialize = (function()
return function(B)
    local A={desires={},since=0} B.arbiter=A
    function A.reset() A.active=nil A.desires={} A.since=0 A.recover=false B.modes.reset() end
    function A.choose(s,emergency)
        local candidates=emergency and {emergency} or B.modes.candidates(s)
        if not emergency then
            if s.hero.hpPct<0.3 or (s.hero.hpPct<0.55 and s.hero.manaPct<0.12) then A.recover=true end
            if s.hero.hpPct>0.82 and s.hero.manaPct>0.55 then A.recover=false end
            if A.recover then candidates[#candidates+1]={name='retreat',key='recover',desire=0.95,
                pos=B.map.home(s),reason='Recover health and mana at base'} end
            local external=B.api and B.api.candidate(s)
            if external then candidates[#candidates+1]=external end
        end
        local best,current
        A.desires={}
        for _,m in ipairs(candidates) do
            m.key=m.key or m.name
            A.desires[m.name]=math.max(A.desires[m.name] or 0,m.desire)
            if not best or m.desire>best.desire then best=m end
            if A.active and m.key==A.active.key then current=m end
        end
        if current and best and not emergency and best.desire<0.84 then
            if s.now-A.since<B.config.modeHold or best.desire<current.desire+0.09 then best=current end
        end
        if not best then best={name='idle',key='idle',desire=0,reason='Waiting for a safe task'} end
        if not A.active or A.active.key~=best.key then
            if A.active then B.modes.onExit(s,A.active) end
            A.since=s.now
            B.log('mode.'..best.key,best.name..': '..best.reason,1)
        end
        A.active=best
        return best
    end
    function A.intent(s,mode)
        if mode.name=='SAFETY' or mode.name=='retreat' then
            return {kind='move',pos=mode.pos,reason=mode.reason,emergency=mode.name=='SAFETY'}
        end
        if mode.external then return B.api.act(s,mode) end
        return B.modes.act(s,mode)
    end
end

end)()
initialize(B)
end

-- MODULE: src/api.lua
do
local initialize = (function()
return function(B)
    local A={sequence=0,completed=0,result='idle'} B.api=A
    local names={'AUTO','STOP','HOLD_SAFE','MOVE_TO','ATTACK_MOVE','RETREAT','GO_FOUNTAIN','GO_TO_LANE',
        'FARM_LANE','PUSH_LANE','DEFEND_LANE','FARM_NEAREST_CAMP','FARM_CAMP','PICKUP_RUNE','SECURE_RUNE',
        'FOLLOW_CORE','GROUP_WITH_TEAM','PLACE_WARD','DEWARD','CONTEST_OBJECTIVE','ATTACK_UNIT','ATTACK_HERO',
        'HARASS_HERO','ATTACK_TOWER','CAST_ABILITY_TARGET','CAST_ABILITY_POSITION','CAST_ABILITY_NO_TARGET',
        'USE_ITEM_TARGET','USE_ITEM_POSITION','USE_ITEM_NO_TARGET','LEVEL_ABILITY','SET_QUICKBUY',
        'CHARGE_HERO','BULLDOZE','NETHER_STRIKE','PLANAR_POCKET','PULL','STACK','ROSHAN','TORMENTOR','OUTPOST'}
    A.allowed={} for _,name in ipairs(names) do A.allowed[name]=true end
    local function idx(v)
        if type(v)=='number' then return v end
        if type(v)=='table' and v.index then return v.index end
        if v then return B.call('Entity','GetIndex',nil,v) end
    end
    function A.finish(seq,ok,reason)
        if seq~=A.sequence then return end
        A.completed=seq A.result=ok and 'success' or 'failed' A.error=not ok and reason or nil
        A.lastReason=reason A.command=nil
    end
    function A.commandAction(action,params,duration)
        if not B.config.externalEnabled then return false,'external_control_disabled' end
        action=type(action)=='string' and action:upper() or ''
        if not A.allowed[action] then return false,'unknown_action' end
        if params~=nil and type(params)~='table' then return false,'params_must_be_table' end
        params=params or {}
        if duration~=nil and (type(duration)~='number' or duration~=duration or duration<0) then return false,'invalid_duration' end
        local clean={}
        for k,v in pairs(params) do clean[k]=v end
        if params.target or params.targetIndex then clean.targetIndex=idx(params.targetIndex or params.target) clean.target=nil end
        if params.position then clean.position=B.pos(params.position) if not clean.position then return false,'invalid_position' end end
        A.sequence=A.sequence+1
        A.command={action=action,params=clean,sequence=A.sequence,
            expires=(B.state and B.state.now or 0)+(duration and duration>0 and math.min(duration,300) or 15)}
        A.result='running' A.error=nil
        if action=='AUTO' then A.finish(A.sequence,true,'Autonomous rules resumed') end
        return true,A.sequence
    end
    function A.cancel() if A.command then A.finish(A.sequence,false,'cancelled') end end
    function A.candidate(s)
        local c=A.command
        if not B.config.externalEnabled or not c then return nil end
        if s.now>=c.expires then A.finish(c.sequence,false,'goal_expired') return nil end
        return {name='external',key='external:'..c.sequence,desire=0.57,reason=c.action,
            external=true,target=s.byIndex[c.params.targetIndex],pos=c.params.position}
    end
    local function move(s,p,reason)
        if not p then return nil end
        if B.dist(s.hero.pos,p)<100 then return {kind='hold',reason=reason} end
        return {kind='move',pos=p,reason=reason}
    end
    local function attack(s,u,reason,allowTower)
        if not u or not u.alive or not u.visible then return nil end
        if u.team==s.hero.team and (not u.name:find('creep') or u.hpPct>=0.5) then return nil end
        if B.dist(s.hero.pos,u.pos)>s.hero.range+35 then
            local i=move(s,B.toward(u.pos,s.hero.pos,math.max(80,s.hero.range-20)),reason)
            if i then i.allowTower=allowTower end return i
        end
        return {kind='attack',target=u,reason=reason,allowTower=allowTower}
    end
    function A.act(s,mode)
        local c=A.command if not c then return nil end
        local a,p=c.action,c.params local t=s.byIndex[p.targetIndex]
        local intent
        if a=='OUTPOST' then A.finish(c.sequence,false,'outpost_capture_unverified') return nil
        elseif a=='STOP' or a=='HOLD_SAFE' then intent={kind='hold',reason=a}
        elseif a=='MOVE_TO' or a=='RETREAT' or a=='GO_FOUNTAIN' then
            local pos=a=='GO_FOUNTAIN' and B.map.home(s) or p.position or (a=='RETREAT' and B.threat.retreat(s))
            if pos and B.dist(pos,s.hero.pos)<120 then A.finish(c.sequence,true,'destination_reached') return nil end
            intent=move(s,pos,a)
        elseif a=='GO_TO_LANE' then intent=move(s,B.map.lanePoint(s,p.lane),a)
        elseif a=='FOLLOW_CORE' or a=='GROUP_WITH_TEAM' then
            t=t or (a=='GROUP_WITH_TEAM' and B.modes and B.modes.groupTarget
                and B.modes.groupTarget(s)) or s.core
            -- This is a macro destination, not a forced move-only loop. Local
            -- protection, combat, items and safety preempt it in the coordinator.
            if t and t.team==s.hero.team and t.alive then intent=move(s,B.toward(t.pos,B.map.home(s),280),a) end
        elseif a=='PICKUP_RUNE' or a=='SECURE_RUNE' then
            t=B.find(s.runes,p.targetIndex)
            if not t then for _,r in ipairs(s.runes) do if not t or B.dist(r.pos,s.hero.pos)<B.dist(t.pos,s.hero.pos) then t=r end end end
            if t then intent=B.dist(t.pos,s.hero.pos)<180 and {kind='rune',target=t,reason=a} or move(s,t.pos,a)
            elseif p.position then intent=move(s,p.position,a) end
        elseif a=='SET_QUICKBUY' then intent={kind='quickbuy',itemName=p.itemName or p.name,reset=p.reset,reason=a}
        elseif a=='PLACE_WARD' then
            local w=s.items['item_ward_'..(p.wardType=='sentry' and 'sentry' or 'observer')]
            if w and p.position then
                if B.dist(s.hero.pos,p.position)>w.range then intent=move(s,B.toward(p.position,s.hero.pos,math.max(90,w.range-40)),a)
                else intent={kind='cast',ability=w,castType='position',pos=p.position,reason=a} end
            end
        elseif a:find('CAST_')==1 or a:find('USE_ITEM')==1 or a=='LEVEL_ABILITY' or a=='CHARGE_HERO' or a=='BULLDOZE' or a=='NETHER_STRIKE' or a=='PLANAR_POCKET' then
            local aliases={CHARGE_HERO='spirit_breaker_charge_of_darkness',BULLDOZE='spirit_breaker_bulldoze',
                NETHER_STRIKE='spirit_breaker_nether_strike',PLANAR_POCKET='spirit_breaker_planar_pocket'}
            local n=aliases[a] or p.abilityName or p.itemName or p.name
            local spell=n and (s.abilities[n] or s.items[n])
            if not spell and (p.abilityIndex or p.itemIndex) then
                for _,v in pairs(p.itemIndex and s.items or s.abilities) do if v.slot==(p.itemIndex or p.abilityIndex) then spell=v break end end
            end
            local kind=(a=='CHARGE_HERO' or a=='NETHER_STRIKE' or a:match('_TARGET$') and not a:match('_NO_TARGET$')) and 'target'
                or a:match('_POSITION$') and 'position' or 'none'
            if spell then intent={kind=a=='LEVEL_ABILITY' and 'level' or 'cast',ability=spell,castType=kind,target=t,pos=p.position,reason=a} end
        elseif a=='ATTACK_UNIT' or a=='ATTACK_HERO' or a=='HARASS_HERO' or a=='DEWARD' or a=='ATTACK_TOWER' or a=='CONTEST_OBJECTIVE' then
            if t and s.time<600 and t.team~=s.hero.team and B.find(s.creeps,t.index) then
                -- External macro cannot bypass support core farm protection.
                for _,v in ipairs(B.modes.candidates(s)) do if v.name=='last_hit' and v.target.index==t.index then intent=v.intent end end
            else intent=attack(s,t,a,a=='ATTACK_TOWER') end
            if not t and p.position then intent=move(s,p.position,a) end
        else
            local mapping={PUSH_LANE={'push','farm'},FARM_LANE={'farm'},DEFEND_LANE={'defend'},
                ROSHAN={'roshan'},TORMENTOR={'tormentor'},PULL={'pull'},STACK={'stack'},ATTACK_MOVE={'fight','farm'}}
            if mapping[a] then
                local best
                for _,m in ipairs(B.modes.candidates(s)) do
                    for _,n in ipairs(mapping[a]) do if m.name==n and (not best or m.desire>best.desire) then best=m end end
                end
                if best then intent=B.modes.act(s,best)
                else intent=move(s,p.position or B.map.lanePoint(s,p.lane),a) end
            elseif a=='FARM_CAMP' or a=='FARM_NEAREST_CAMP' then
                if s.time>=600 then
                    local camp=B.find(s.camps,p.campIndex or p.camp)
                    if not camp then for _,v in ipairs(s.camps) do if not camp or B.dist(v.pos,s.hero.pos)<B.dist(camp.pos,s.hero.pos) then camp=v end end end
                    if camp then
                        for _,n in ipairs(B.near(s.neutrals,camp.pos,500)) do if not t or n.hp<t.hp then t=n end end
                        intent=t and attack(s,t,a) or move(s,camp.pos,a)
                    end
                end
            end
        end
        if intent then intent.sequence=c.sequence return intent end
        A.finish(c.sequence,false,'no_valid_target_or_capability')
    end
    local function clean(value,depth)
        if depth>10 then return nil end
        if type(value)=='number' or type(value)=='boolean' or type(value)=='string' then return value end
        if type(value)~='table' then return nil end
        local out={}
        for k,v in pairs(value) do if k~='handle' and k~='player' and k~='byIndex' and k~='mods' then out[k]=clean(v,depth+1) end end
        return out
    end
    function A.observation()
        local s=B.state
        local out=s and clean(s,0) or {ready=false}
        out.ready=s~=nil out.botEnabled=B.enabled out.aiEnabled=B.enabled out.recordingEnabled=false
        out.action=A.command and A.command.action or 'AUTO' out.actionSequence=A.sequence out.sequence=A.sequence
        out.completedSequence=A.completed out.lastResult=A.result out.lastError=A.error
        out.activeMode=B.arbiter.active and B.arbiter.active.name or 'waiting'
        out.modeDesires=B.arbiter.desires out.decisionReason=B.arbiter.active and B.arbiter.active.reason
        out.targetIndex=B.arbiter.active and B.arbiter.active.target and B.arbiter.active.target.index
        out.route=clean(B.navigation.route,0) out.version=B.version out.externalEnabled=B.config.externalEnabled
        out.capabilities=clean(B.capabilities,0) out.orders=B.executor.count
        out.purchaseStatus=B.items.status
        if s then
            out.hero.position=out.hero.pos out.hero.health=out.hero.hp out.hero.maxHealth=out.hero.maxHp
            out.hero.healthPercent=out.hero.hpPct out.hero.attackRange=out.hero.range
            out.gameTime=s.time
        end
        return out
    end
    local api={Command=A.commandAction,Cancel=A.cancel,GetObservation=A.observation}
    function api.SetExternalEnabled(enabled) B.config.externalEnabled=enabled==true if not B.config.externalEnabled then A.cancel() end end
    function api.SetEnabled(enabled) B.setEnabled(enabled==true) end
    local wrappers={MoveTo={'MOVE_TO','position'},AttackMove={'ATTACK_MOVE','position'},FarmLane={'FARM_LANE','lane'},
        GoToLane={'GO_TO_LANE','lane'},PushLane={'PUSH_LANE','lane'},DefendLane={'DEFEND_LANE','lane'},
        FarmCamp={'FARM_CAMP','campIndex'},PickupRune={'PICKUP_RUNE','target'},FollowCore={'FOLLOW_CORE','target'},
        GroupWithTeam={'GROUP_WITH_TEAM','target'},Deward={'DEWARD','target'},Retreat={'RETREAT','position'},
        AttackHero={'ATTACK_HERO','target'},AttackUnit={'ATTACK_UNIT','target'},HarassHero={'HARASS_HERO','target'},
        AttackTower={'ATTACK_TOWER','target'},ChargeHero={'CHARGE_HERO','target'},NetherStrike={'NETHER_STRIKE','target'},
        LevelAbility={'LEVEL_ABILITY','name'}}
    for method,def in pairs(wrappers) do local action,key=def[1],def[2] api[method]=function(value,duration) return A.commandAction(action,{[key]=value},duration) end end
    for method,action in pairs({FarmNearestCamp='FARM_NEAREST_CAMP',GoFountain='GO_FOUNTAIN',HoldSafe='HOLD_SAFE',Bulldoze='BULLDOZE',PlanarPocket='PLANAR_POCKET'}) do
        local a=action api[method]=function(duration) return A.commandAction(a,{},duration) end
    end
    for method,action in pairs({CastAbilityTarget='CAST_ABILITY_TARGET',CastAbilityPosition='CAST_ABILITY_POSITION',CastAbilityNoTarget='CAST_ABILITY_NO_TARGET',
        UseItemTarget='USE_ITEM_TARGET',UseItemPosition='USE_ITEM_POSITION',UseItemNoTarget='USE_ITEM_NO_TARGET'}) do
        local a=action api[method]=function(name,value) return A.commandAction(a,{name=name,target=a:match('_TARGET$') and not a:match('_NO_TARGET$') and value or nil,position=a:match('_POSITION$') and value or nil},5) end
    end
    function api.PlaceWard(pos,kind) return A.commandAction('PLACE_WARD',{position=pos,wardType=kind},15) end
    function api.SetQuickBuy(name,reset) return A.commandAction('SET_QUICKBUY',{itemName=name,reset=reset},5) end
    function api.SecureRune(target,pos,duration) return A.commandAction('SECURE_RUNE',{target=target,position=pos},duration) end
    function api.ContestObjective(target,pos,duration) return A.commandAction('CONTEST_OBJECTIVE',{target=target,position=pos},duration) end
    B.public=api
    DotaAI=api
end

end)()
initialize(B)
end

-- MODULE: src/json.lua
do
local initialize = (function()
return function(B)
local J={}
function J.json_escape(value)
    return string.gsub(value, '[%z\1-\31\\"]', function(character)
        local replacements = {
            ['"'] = '\\"',
            ['\\'] = '\\\\',
            ['\b'] = '\\b',
            ['\f'] = '\\f',
            ['\n'] = '\\n',
            ['\r'] = '\\r',
            ['\t'] = '\\t',
        }
        return replacements[character] or string.format("\\u%04x", string.byte(character))
    end)
end


function J.json_encode(value, stack)
    local value_type = type(value)
    if value == nil then
        return "null"
    elseif value_type == "boolean" then
        return value and "true" or "false"
    elseif value_type == "number" then
        if value ~= value or value == math.huge or value == -math.huge then
            return "null"
        end
        return tostring(value)
    elseif value_type == "string" then
        return '"' .. J.json_escape(value) .. '"'
    elseif value_type ~= "table" then
        return '"' .. J.json_escape(tostring(value)) .. '"'
    end

    stack = stack or {}
    if stack[value] then
        error("circular table in JSON")
    end
    stack[value] = true
    local is_array = true
    local max_index = 0
    for key in pairs(value) do
        if type(key) ~= "number" or key < 1 or key % 1 ~= 0 then
            is_array = false
            break
        end
        max_index = math.max(max_index, key)
    end
    local parts = {}
    if is_array then
        for index = 1, max_index do
            parts[#parts + 1] = J.json_encode(value[index], stack)
        end
        stack[value] = nil
        return "[" .. table.concat(parts, ",") .. "]"
    end
    for key, item in pairs(value) do
        if type(key) == "string" then
            parts[#parts + 1] = '"' .. J.json_escape(key) .. '":'
                .. J.json_encode(item, stack)
        end
    end
    stack[value] = nil
    return "{" .. table.concat(parts, ",") .. "}"
end

function J.json_decode(text)
    local position = 1
    local length = #text
    local parse_value
    local depth=0
    local function utf8char(code)
        if code<128 then return string.char(code) end
        if code<2048 then return string.char(192+math.floor(code/64),128+code%64) end
        if code<65536 then return string.char(224+math.floor(code/4096),128+math.floor(code/64)%64,128+code%64) end
        return string.char(240+math.floor(code/262144),128+math.floor(code/4096)%64,128+math.floor(code/64)%64,128+code%64)
    end

    local function skip_space()
        while position <= length and string.match(string.sub(text, position, position), "%s") do
            position = position + 1
        end
    end

    local function parse_string()
        position = position + 1
        local parts = {}
        while position <= length do
            local character = string.sub(text, position, position)
            if character == '"' then
                position = position + 1
                return table.concat(parts)
            elseif character == "\\" then
                local escaped = string.sub(text, position + 1, position + 1)
                local replacements = {
                    ['"'] = '"', ['\\'] = '\\', ['/'] = '/',
                    b = '\b', f = '\f', n = '\n', r = '\r', t = '\t',
                }
                if escaped == "u" then
                    local code = tonumber(string.sub(text, position + 2, position + 5), 16)
                    if not code then error("invalid JSON unicode escape") end
                    position = position + 6
                    if code>=55296 and code<=56319 then
                        if text:sub(position,position+1)~='\\u' then error('unpaired JSON surrogate') end
                        local low=tonumber(text:sub(position+2,position+5),16)
                        if not low or low<56320 or low>57343 then error('invalid JSON surrogate') end
                        code=65536+(code-55296)*1024+low-56320
                        position=position+6
                    elseif code>=56320 and code<=57343 then error('unpaired JSON surrogate') end
                    parts[#parts + 1] = utf8char(code)
                else
                    parts[#parts + 1] = replacements[escaped] or escaped
                    position = position + 2
                end
            else
                parts[#parts + 1] = character
                position = position + 1
            end
        end
        error("unterminated JSON string")
    end

    local function parse_number()
        local start = position
        while position <= length and string.match(string.sub(text, position, position), "[%d%+%-%eE%.]") do
            position = position + 1
        end
        local number = tonumber(string.sub(text, start, position - 1))
        if number == nil then error("invalid JSON number") end
        return number
    end

    local function parse_array()
        position = position + 1
        local result = {}
        skip_space()
        if string.sub(text, position, position) == "]" then
            position = position + 1
            return result
        end
        while true do
            result[#result + 1] = parse_value()
            skip_space()
            local character = string.sub(text, position, position)
            if character == "]" then
                position = position + 1
                return result
            elseif character ~= "," then
                error("invalid JSON array")
            end
            position = position + 1
        end
    end

    local function parse_object()
        position = position + 1
        local result = {}
        skip_space()
        if string.sub(text, position, position) == "}" then
            position = position + 1
            return result
        end
        while true do
            skip_space()
            if string.sub(text, position, position) ~= '"' then error("invalid JSON object key") end
            local key = parse_string()
            skip_space()
            if string.sub(text, position, position) ~= ":" then error("missing JSON colon") end
            position = position + 1
            result[key] = parse_value()
            skip_space()
            local character = string.sub(text, position, position)
            if character == "}" then
                position = position + 1
                return result
            elseif character ~= "," then
                error("invalid JSON object")
            end
            position = position + 1
        end
    end

    parse_value = function()
        skip_space()
        local character = string.sub(text, position, position)
        if character == '"' then return parse_string() end
        if character == '{' or character == '[' then
            depth=depth+1 if depth>32 then error('JSON nesting limit') end
            local v=character=='{' and parse_object() or parse_array()
            depth=depth-1 return v
        end
        if string.sub(text, position, position + 3) == "true" then position = position + 4; return true end
        if string.sub(text, position, position + 4) == "false" then position = position + 5; return false end
        if string.sub(text, position, position + 3) == "null" then position = position + 4; return nil end
        return parse_number()
    end

    local result = parse_value()
    skip_space()
    if position <= length then error("trailing JSON data") end
    return result
end



B.json={encode=function(_,v) return J.json_encode(v) end,decode=function(_,v) return J.json_decode(v) end}
end

end)()
initialize(B)
end

-- MODULE: src/bridge.lua
do
local initialize = (function()
-- Optional future macro transport. No recorder; never required by autonomy.
return function(B)
    local T={nextAt=0,generation=0,connected=false} B.bridge=T
    function B.public.SetBridgeEnabled(enabled)
        B.config.bridgeEnabled=enabled==true T.generation=T.generation+1 T.inFlight=false
        if not enabled then T.connected=false end
    end
    function T.tick(s)
        if not B.config.bridgeEnabled or not B.config.externalEnabled or not B.enabled then return end
        if T.inFlight and s.now-T.started>4 then T.inFlight=false T.generation=T.generation+1 end
        if T.inFlight or s.now<T.nextAt then return end
        T.nextAt=s.now+1
        if not T.json then
            T.json=B.json
        end
        local obs=B.api.observation()
        obs.bridgeCommandId=T.commandId obs.bridgeCommandSequence=T.sequence
        obs.bridgeGoalId=T.goalId obs.bridgeCommandLayer='macro'
        local ok,data=pcall(function() return T.json:encode({protocolVersion=1,clientTime=s.now,
            aiEnabled=true,recordingEnabled=false,observation=obs}) end)
        if not ok then B.log('bridge.encode','Optional bridge encoding failed',30) return end
        if not HTTP or not HTTP.Request then B.log('bridge.http','Optional HTTP transport unavailable',30) return end
        T.inFlight=true T.started=s.now
        local generation=T.generation
        local sent,err=pcall(HTTP.Request,'POST','http://127.0.0.1:8765/v1/tick',{data=data},function(response)
            if generation~=T.generation then return end
            T.inFlight=false
            if not B.config.bridgeEnabled or not B.config.externalEnabled or not B.enabled then return end
            if not response or tostring(response.code)~='200' then T.connected=false B.log('bridge.offline','Optional bridge offline; continuing autonomous rules',15) return end
            if type(response.response)~='string' or #response.response>131072 then T.connected=false return end
            local parsed,payload=pcall(function() return T.json:decode(response.response) end)
            if not parsed or type(payload)~='table' then T.connected=false return end
            T.connected=true
            local c=payload.command
            -- External service owns only macro goals. Micro remains local even
            -- if a legacy bridge attempts to send its old micro command layer.
            if payload.observeOnly==false and type(c)=='table' and c.layer=='macro' and c.id and c.id~=T.commandId then
                local accepted,sequence=B.api.commandAction(c.action,c.params,tonumber(c.duration) or 10)
                if accepted then T.commandId=c.id T.sequence=sequence T.goalId=c.goalId end
            end
        end)
        if not sent or err==false then T.inFlight=false T.connected=false B.log('bridge.send','Optional HTTP request failed',15) end
    end
    function T.reset() T.inFlight=false T.nextAt=0 T.generation=T.generation+1 T.commandId=nil T.connected=false end
end

end)()
initialize(B)
end

-- MODULE: src/chat.lua
do
local initialize = (function()
-- Match-chat receiver and voice-reply transport. LLM/TTS stay outside Dota.
return function(B)
    local C={nextPoll=0,polling=false,listenUntil=0,recording=false,stopAt=0}
    B.chatVoice=C B.voiceStatus='idle'
    local protobuf
    local ok,loaded=pcall(require,'protobuf')
    if ok then protobuf=loaded end

    local function post(path,payload,callback)
        if not HTTP or type(HTTP.Request)~='function' then return false end
        local encoded,data=pcall(function() return B.json:encode(payload) end)
        if not encoded then return false end
        local sent=pcall(HTTP.Request,'POST','http://127.0.0.1:8765'..path,{data=data},callback or function() end)
        return sent
    end
    local function playerInfo(sourceId)
        local localPlayer=B.call('Players','GetLocal',nil)
        local localHero=localPlayer and B.call('Player','GetAssignedHero',nil,localPlayer)
        local localTeam=localHero and B.call('Entity','GetTeamNum',-1,localHero) or -1
        local localId=localPlayer and B.call('Player','GetPlayerID',-1,localPlayer) or -1
        local localName='OpenAI bot'
        if localPlayer then
            local named,name=pcall(function() return B.libs.Player.GetName(localPlayer) end)
            if named and type(name)=='string' and #name>0 then localName=name end
        end
        local info={sourcePlayerId=sourceId,isSelf=sourceId==localId,isAlly=false,
            sourceName='Player '..tostring(sourceId),sourceHero='unknown',localName=localName}
        for _,player in pairs(B.call('Players','GetAll',{})) do
            if B.call('Player','GetPlayerID',-2,player)==sourceId then
                local hero=B.call('Player','GetAssignedHero',nil,player)
                local team=hero and B.call('Entity','GetTeamNum',-2,hero) or -2
                local named,name=pcall(function() return B.libs.Player.GetName(player) end)
                if named and type(name)=='string' and #name>0 then info.sourceName=name end
                if hero then info.sourceHero=B.call('NPC','GetUnitName','unknown',hero) end
                info.isAlly=localTeam>=0 and team==localTeam
                break
            end
        end
        return info
    end
    function C.handleDecoded(message)
        if not B.enabled or type(message)~='table' then return true end
        local text=message.message_text
        local sourceId=tonumber(message.source_player_id)
        if type(text)~='string' or #text==0 or #text>1024 or not sourceId then return true end
        local info=playerInfo(sourceId)
        local lowered=text:lower()
        local selfTest=info.isSelf and (lowered:find('бара',1,true)~=nil or
            lowered:find('bara',1,true)~=nil or lowered:find('spirit breaker',1,true)~=nil)
        if info.isSelf and not selfTest then return true end
        local payload={protocolVersion=1,messageText=text,channelType=tonumber(message.channel_type) or 0,
            gameTime=B.state and B.state.time or 0,sourcePlayerId=sourceId,sourceName=info.sourceName,
            sourceHero=info.sourceHero,isAlly=info.isAlly,isSelf=info.isSelf,selfTest=selfTest,
            localName=info.localName}
        C.listenUntil=(B.state and B.state.now or 0)+60
        B.voiceStatus='analyzing '..info.sourceName
        post('/v1/chat',payload,function(response)
            if not response or tostring(response.code)~='202' then
                B.voiceStatus='chat bridge offline'
                B.log('chat.voice.offline','Chat responder bridge unavailable',15)
            end
        end)
        return true
    end
    function C.onNetMessage(msg)
        if not msg or msg.message_id~=612 or not msg.msg_object then return true end
        if not protobuf or type(protobuf.decodeToJSONfromObject)~='function' then
            B.log('chat.protobuf','protobuf decoder unavailable for match chat',30) return true
        end
        local decoded,json=pcall(protobuf.decodeToJSONfromObject,msg.msg_object)
        if not decoded or type(json)~='string' then return true end
        local parsed,message=pcall(function() return B.json:decode(json) end)
        if parsed then return C.handleDecoded(message) end
        return true
    end
    local function startVoice(job,s)
        if C.recording or type(job.id)~='string' then return end
        local duration=math.max(0.2,math.min(15,tonumber(job.duration) or 2))
        local commandOk=pcall(B.libs.Engine.ExecuteCommand,'+voicerecord')
        if not commandOk then B.voiceStatus='voice command failed' return end
        C.recording=true C.stopAt=s.now+duration+0.25
        B.voiceStatus='speaking: '..tostring(job.text or '')
        post('/v1/voice/start',{id=job.id},function(response)
            if not response or tostring(response.code)~='200' then
                B.log('chat.voice.start','TTS playback did not start',10)
            end
        end)
    end
    function C.tick(s)
        if C.recording and s.now>=C.stopAt then
            pcall(B.libs.Engine.ExecuteCommand,'-voicerecord')
            C.recording=false B.voiceStatus='idle'
        end
        if C.recording or C.polling or s.now<C.nextPoll or s.now>C.listenUntil then return end
        C.nextPoll=s.now+0.35 C.polling=true
        local sent=post('/v1/voice/poll',{},function(response)
            C.polling=false
            if not response or tostring(response.code)~='200' or type(response.response)~='string' then return end
            local parsed,job=pcall(function() return B.json:decode(response.response) end)
            if parsed and type(job)=='table' and job.ready then startVoice(job,s) end
        end)
        if not sent then C.polling=false end
    end
    function C.reset()
        if C.recording and B.libs.Engine and type(B.libs.Engine.ExecuteCommand)=='function' then
            pcall(B.libs.Engine.ExecuteCommand,'-voicerecord')
        end
        C.nextPoll=0 C.polling=false C.listenUntil=0 C.recording=false C.stopAt=0
        B.voiceStatus='idle'
    end
end

end)()
initialize(B)
end

-- MODULE: src/ui.lua
do
local initialize = (function()
return function(B)
    local U={x=40,y=145,w=154,h=40,down=false} B.ui=U
    function U.input()
        if not Input or not Enum or not Enum.ButtonCode then return end
        local x,y=Input.GetCursorPos()
        if type(x)~='number' or type(y)~='number' then return end
        local down=Input.IsKeyDown(Enum.ButtonCode.KEY_MOUSE1)
        local inside=x>=U.x and x<=U.x+U.w and y>=U.y and y<=U.y+U.h
        if down and not U.down and inside then U.press={x=x,y=y,ox=U.x,oy=U.y} U.drag=false end
        if down and U.press then
            local dx,dy=x-U.press.x,y-U.press.y
            if dx*dx+dy*dy>25 then U.drag=true end
            if U.drag then U.x=math.max(0,U.press.ox+dx) U.y=math.max(0,U.press.oy+dy) end
        elseif not down and U.down and U.press then
            if not U.drag and inside then B.setEnabled(not B.enabled) end
            U.press=nil U.drag=false
        end
        U.down=down
    end
    function U.draw()
        if not Render or not Vec2 or not Color then return end
        if not U.font then U.font=Render.LoadFont('Arial',18,600) end
        local a,b=Vec2(U.x,U.y),Vec2(U.x+U.w,U.y+U.h)
        Render.FilledRect(a,b,B.enabled and Color(37,153,75,235) or Color(162,52,52,235),7)
        Render.Rect(a,b,Color(255,255,255,235),7)
        local label=B.enabled and 'Bot: ON' or 'Bot: OFF'
        local size=Render.TextSize(U.font,18,label)
        Render.Text(U.font,18,label,Vec2(U.x+(U.w-size.x)/2,U.y+10),Color(255,255,255))
        local status=B.error and 'ERROR: '..B.error or not B.state and 'Spirit Breaker only | '..B.version
            or ('pos '..B.state.role..' | lv '..B.state.hero.level..' | '..(B.arbiter.active and B.arbiter.active.name or 'ready'))
        Render.Text(U.font,12,status,Vec2(U.x,U.y+44),Color(240,240,240))
        if B.state then Render.Text(U.font,12,'Shop: '..(B.items.status or 'waiting'),Vec2(U.x,U.y+59),Color(240,220,160)) end
        if B.state then Render.Text(U.font,12,'Voice: '..(B.voiceStatus or 'idle'),Vec2(U.x,U.y+74),Color(190,225,255)) end
        if B.state and not B.chatSent then
            Render.Text(U.font,12,'Chat: '..(B.chatStatus or 'waiting'),Vec2(U.x,U.y+89),Color(220,220,240))
        end
    end
end

end)()
initialize(B)
end

-- MODULE: src/main.lua
do
local initialize = (function()
return function(B)
    local nextDecision=0
    local greeted,greetingNext=false,0
    B.chatStatus='waiting' B.chatSent=false
    local function reset()
        B.adapter.reset() B.navigation.reset() B.arbiter.reset() B.executor.reset()
        B.items.reset() B.hero.reset() B.api.cancel() B.bridge.reset()
        if B.chatVoice then B.chatVoice.reset() end
        B.state=nil nextDecision=0 B.error=nil
        greeted,greetingNext=false,0
        B.chatStatus='waiting' B.chatSent=false
    end
    local function greet(s)
        if greeted or not s or type(s.time)~='number' or s.time<0
            or type(s.now)~='number' or s.now<greetingNext then return end
        greetingNext=s.now+2
        -- Chat.Say targets the dashboard/GC channel list, not Dota's live
        -- match chat. Umbrella exposes the same console path that Dota uses:
        -- `say` is all-chat and `say_team` is allied chat.
        if not B.libs.Engine or type(B.libs.Engine.ExecuteCommand)~='function' then
            B.chatStatus='Engine.ExecuteCommand unavailable' return
        end
        local ok,err=pcall(B.libs.Engine.ExecuteCommand,'say "Удачи и веселой игры"')
        if ok then
            greeted=true B.chatSent=true B.chatStatus='all-chat command sent'
            B.log('chat.greeting','Executed one all-chat greeting with Engine.ExecuteCommand',0)
        else
            B.chatStatus='send failed; retrying'
            B.log('chat.error','Engine.ExecuteCommand: '..tostring(err),5)
        end
    end
    function B.setEnabled(value)
        if B.enabled==value then return end
        if not value then B.executor.stop(B.state) end
        B.enabled=value B.config.botEnabled=value B.api.cancel() B.arbiter.reset() B.navigation.reset()
        B.items.reset()
        B.error=nil nextDecision=0
        B.log('toggle','Bot '..(value and 'ON' or 'OFF'),0)
    end
    local function tick()
        DotaAI=B.public
        B.ui.input()
        local now=B.call('GameRules','GetGameTime',0)
        if B.state and now<B.state.now then reset() end
        local localHero=B.call('Heroes','GetLocal',nil)
        if not localHero or B.call('NPC','GetUnitName','',localHero)~='npc_dota_hero_spirit_breaker' then
            if B.state then reset() end return
        end
        if B.state and not B.enabled then return end
        if B.state then B.adapter.quick(B.state) end
        local full=not B.state or now>=nextDecision
        if full then
            nextDecision=now+B.config.decisionInterval
            B.state=B.adapter.refresh()
        end
        local s=B.state
        if not s or not B.enabled then return end
        if B.chatVoice then B.chatVoice.tick(s) end
        if not s.hero.alive then return end
        greet(s)
        B.log('status','Active pos '..s.role..' ('..tostring(s.laneSelectionFlags)..') | orders '..B.executor.count,15)
        B.executor.poll(s)
        -- Small cached-state safety scan every callback. Full decisions at 8.3Hz.
        local emergency=B.threat.safety(s)
        if not full and not emergency then return end
        local mode=B.arbiter.choose(s,emergency)
        local proposal=B.arbiter.intent(s,mode)
        if full and proposal and proposal.pos then B.log('destination','Destination '..mode.name..' '..math.floor(proposal.pos.x)..','..math.floor(proposal.pos.y)..' | core '..tostring(mode.target and mode.target.index),15) end
        local item=B.items.consider(s,mode)
        local spell=B.hero.consider(s,mode)
        local micro=item
        if spell and (not micro or (spell.priority or 0)>(micro.priority or 0)) then micro=spell end
        -- Instant defensive casts can precede a retreat without allowing an
        -- offensive Charge to override a safety move.
        if micro and (not emergency or (micro.priority or 0)>=89 or micro.ability.name=='spirit_breaker_bulldoze') then
            if B.executor.execute(s,micro) then return end
        end
        if full and not emergency then
            local cleanup=B.items.cleanup(s)
            if cleanup and B.executor.execute(s,cleanup) then return end
            local purchase=B.items.purchase(s)
            if purchase then B.executor.execute(s,purchase) end
            if not B.executor.pending then
                local level=B.hero.level(s)
                if level and B.executor.execute(s,level) then return end
            end
        end
        if proposal then
            local accepted=B.executor.execute(s,proposal)
            if accepted and proposal.sequence and proposal.kind=='quickbuy' then B.api.finish(proposal.sequence,true,'Quick-buy command accepted') end
        end
        if full then B.bridge.tick(s) end
    end
    function B.script.OnUpdate()
        local ok,err=pcall(tick)
        if not ok then
            B.error=tostring(err) B.log('fatal',B.error,3)
            if B.enabled then B.executor.stop(B.state) end
            B.enabled=false -- Surface errors; do not keep sending corrupted orders.
        end
    end
    function B.script.OnDraw()
        local ok,err=pcall(B.ui.draw)
        if not ok then B.log('ui.error',tostring(err),10) end
    end
    function B.script.OnProjectile(p)
        if B.adapter.projectile then B.adapter.projectile(p) end
    end
    function B.script.OnPostReceivedNetMessage(msg)
        if B.chatVoice then return B.chatVoice.onNetMessage(msg) end
        return true
    end
    function B.script.OnGameStart() reset() B.enabled=B.config.botEnabled end
    function B.script.OnGameEnd() reset() end
    function B.script.OnScriptUnload() B.executor.stop(B.state) if B.chatVoice then B.chatVoice.reset() end if DotaAI==B.public then DotaAI=nil end end
    B.log('loaded','Loaded autonomous controller; recorder OFF, external OFF',0)
end

end)()
initialize(B)
end

return B.script
